import { supabase } from "@/integrations/supabase/client";

// Client-side dedup: skip if same error logged within the last 30 seconds
const recentErrors = new Map<string, number>();

/**
 * Log a frontend runtime error to system_error_logs via the log-client-error edge function.
 * Safe to call from anywhere — never throws.
 */
export async function logClientError(
  errorType: string,
  source: string,
  message: string,
  stack?: string,
  extra?: Record<string, unknown>,
): Promise<void> {
  try {
    const key = `${source}:${message.slice(0, 120)}`;
    const now = Date.now();
    if ((recentErrors.get(key) ?? 0) > now - 30_000) return; // dedup
    recentErrors.set(key, now);

    // Clean up old entries to avoid memory leak
    if (recentErrors.size > 100) {
      const cutoff = now - 60_000;
      for (const [k, t] of recentErrors.entries()) {
        if (t < cutoff) recentErrors.delete(k);
      }
    }

    const { data: { user } } = await supabase.auth.getUser();

    await supabase.functions.invoke("log-client-error", {
      body: {
        error_type: errorType,
        function_name: source,
        severity: "warning",
        error_message: message,
        error_stack: stack,
        context_json: extra ?? {},
        user_id: user?.id ?? null,
      },
    });
  } catch {
    // Never throw from an error logger
  }
}
