import { Button } from "@/components/ui/button";
import { Lightbulb, Wand2 } from "lucide-react";
import type { Result } from "@/pages/Index";

interface AINudgePanelProps {
  result: Result;
  onRewriteJd?: () => void;
}

const AINudgePanel = ({ result: r, onRewriteJd }: AINudgePanelProps) => {
  const tradeoffs = r.explanation_json?.key_tradeoffs;
  const confidence = r.confidence ?? 0;
  const hasGaps = (r.gaps_json || r.missing_must_haves || []).length > 0;

  if (!tradeoffs && confidence >= 70 && !hasGaps) return null;

  return (
    <div className="p-3 rounded-lg bg-amber-500/5 border border-amber-500/20">
      <div className="flex items-start gap-2">
        <Lightbulb className="h-4 w-4 text-amber-500 shrink-0 mt-0.5" />
        <div className="flex-1 space-y-2">
          <h5 className="text-xs font-semibold text-foreground">AI Suggestion</h5>
          {tradeoffs && (
            <p className="text-xs text-muted-foreground leading-relaxed">{tradeoffs}</p>
          )}
          {confidence < 70 && (
            <p className="text-xs text-muted-foreground leading-relaxed">
              Confidence: {confidence.toFixed(0)}% — {confidence < 40 ? "Low confidence. Resume may lack detail for accurate scoring." : "Medium confidence. Some scoring dimensions had limited evidence."}
            </p>
          )}
          {hasGaps && onRewriteJd && (
            <div className="flex items-center gap-2 pt-1">
              <p className="text-xs text-muted-foreground">Softening requirements could improve this candidate's score.</p>
              <Button
                variant="outline"
                size="sm"
                className="h-7 text-xs gap-1.5 shrink-0"
                onClick={(e) => {
                  e.stopPropagation();
                  onRewriteJd();
                }}
              >
                <Wand2 className="h-3 w-3" />
                Rewrite JD
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AINudgePanel;

