  isDuplicate?: boolean;
}

const getScoreColor = (score: number) => {
  if (score >= 70) return "bg-score-skills";
  if (score >= 40) return "bg-warning";
  return "bg-destructive";
};

const getScoreTextColor = (score: number) => {
  if (score >= 70) return "text-score-skills";
  if (score >= 40) return "text-warning";
  return "text-destructive";
};

const STAGE_BADGE_CLASSES: Record<string, string> = {
  applied: "border-border bg-muted/50 text-muted-foreground",
  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
};

const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

const getRankDisplay = (index: number) => {
  if (index < 3) {
    const colors = [
      "bg-score-overall text-white dark:text-white",
      "bg-muted-foreground/60 text-white dark:text-white",
      "bg-warning text-warning-foreground",
    ];
    return (
      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
        {index + 1}
      </span>
    );
  }
  return (
    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
      {index + 1}
    </span>
  );
};

