  1→import { useState } from "react";
  2→import { Button } from "@/components/ui/button";
  3→import { Badge } from "@/components/ui/badge";
  4→import { Checkbox } from "@/components/ui/checkbox";
  5→import { TableCell, TableRow } from "@/components/ui/table";
  6→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  7→import { Phone, Mail, MapPin, FileText, Archive } from "lucide-react";
  8→import { toast } from "sonner";
  9→import type { Result } from "@/pages/Index";
 10→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 11→import type { HiringStage } from "@/hooks/useStageTracker";
 12→
 13→interface CandidateRowProps {
 14→  result: Result;
 15→  index: number;
 16→  isSelected: boolean;
 17→  isActive: boolean;
 18→  jobId?: string | null;
 19→  jobTitle?: string | null;
 20→  onSelect: (id: string) => void;
 21→  onToggleSelect: (resumeId: string) => void;
 22→  onDownload: (filePath: string, filename: string) => void;
 23→  onDismiss: (resumeId: string) => void;
 24→  formatCandidateName: (filename: string) => string;
 25→  currentStage?: HiringStage | null;
 26→  isDuplicate?: boolean;
 27→}
 28→
 29→const getScoreColor = (score: number) => {
 30→  if (score >= 70) return "bg-score-skills";
 31→  if (score >= 40) return "bg-warning";
 32→  return "bg-destructive";
 33→};
 34→
 35→const getScoreTextColor = (score: number) => {
 36→  if (score >= 70) return "text-score-skills";
 37→  if (score >= 40) return "text-warning";
 38→  return "text-destructive";
 39→};
 40→
 41→const STAGE_BADGE_CLASSES: Record<string, string> = {
 42→  applied: "border-border bg-muted/50 text-muted-foreground",
 43→  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
 44→  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
 45→  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
 46→  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
 47→  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
 48→};
 49→
 50→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 51→  if (score >= 70) return { label: "Strong", variant: "success" };
 52→  if (score >= 40) return { label: "Good", variant: "warning" };
 53→  return { label: "Weak", variant: "destructive" };
 54→};
 55→
 56→const CandidateRow = ({
 57→  result: r,
 58→  index,
 59→  isSelected,
 60→  isActive,
 61→  jobId,
 62→  jobTitle,
 63→  onSelect,
 64→  onToggleSelect,
 65→  onDownload,
 66→  onDismiss,
 67→  formatCandidateName,
 68→  currentStage,
 69→  isDuplicate,
 70→}: CandidateRowProps) => {
 71→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
 72→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
 73→
 74→  return (
 75→    <>
 76→      <TableRow
 77→        className={`cursor-pointer transition-colors animate-in fade-in slide-in-from-bottom-1 duration-200 ${isActive ? "bg-primary/5 hover:bg-primary/5" : "hover:bg-muted/50"}`}
 78→        style={{ animationDelay: `${Math.min(index * 40, 400)}ms`, animationFillMode: "backwards" }}
 79→        onClick={() => !r.pending && onSelect(r.id)}
 80→      >
 81→        <TableCell onClick={(e) => e.stopPropagation()}>
 82→          <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
 83→        </TableCell>
 84→        <TableCell className="text-center">
 85→          {r.pending
 86→            ? <span className="text-sm text-muted-foreground">—</span>
 87→            : <span className="text-sm font-medium tabular-nums text-muted-foreground">{index + 1}</span>}
 88→        </TableCell>
 89→        <TableCell className="font-medium">
 90→          <div className="flex flex-col gap-0.5">
 91→            <div className="flex items-center gap-1.5 flex-wrap">
 92→              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
 93→              {isDuplicate && (
 94→                <Badge variant="outline" className="text-[10px] px-1.5 py-0 border-orange-300 text-orange-600 bg-orange-50">
 95→                  Duplicate
 96→                </Badge>
 97→              )}
 98→              {!r.pending && currentStage && currentStage !== "applied" && (
 99→                <Badge
100→                  variant="outline"
101→                  className={`text-[10px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
102→                >
103→                  {currentStage}
104→                </Badge>
105→              )}
106→            </div>
107→            {r.candidate_location && (
108→              <span className="flex items-center gap-1 text-xs text-muted-foreground">
109→                <MapPin className="h-3 w-3" /> {r.candidate_location}
110→              </span>
111→            )}
112→          </div>
113→        </TableCell>
114→        <TableCell>
115→          {r.pending ? (
116→            <Badge variant="outline" className="text-xs">Pending</Badge>
117→          ) : (
118→            <div className="flex items-center gap-2">
119→              <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
120→                <div
121→                  className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
122→                  style={{ width: `${Math.min(r.overall_score, 100)}%` }}
123→                />
124→              </div>
125→              <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
126→                {r.overall_score?.toFixed(0)}%
127→              </span>
128→            </div>
129→          )}
130→        </TableCell>
131→        <TableCell>
132→          <div className="flex flex-wrap items-center gap-1">
133→            {!r.pending && strength && (
134→              <Badge variant={strength.variant} className="text-[10px]">{strength.label}</Badge>
135→            )}
136→            {!r.pending && r.scoring_version === "heuristic" && (
137→              <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium">Quick</span>
138→            )}
139→          </div>
140→        </TableCell>
141→        <TableCell>
142→          <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
143→            <TooltipProvider delayDuration={300}>
144→              {r.candidate_phone && (
145→                <Tooltip>
146→                  <TooltipTrigger asChild>
147→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
148→                      onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
149→                      <Phone className="h-3.5 w-3.5" />
150→                    </Button>
151→                  </TooltipTrigger>
152→                  <TooltipContent>{r.candidate_phone}</TooltipContent>
153→                </Tooltip>
154→              )}
155→              {r.candidate_email && (
156→                <Tooltip>
157→                  <TooltipTrigger asChild>
158→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
159→                      onClick={() => setEmailDialogOpen(true)}>
160→                      <Mail className="h-3.5 w-3.5" />
161→                    </Button>
162→                  </TooltipTrigger>
163→                  <TooltipContent>Email</TooltipContent>
164→                </Tooltip>
165→              )}
166→              {r.file_path && (
167→                <Tooltip>
168→                  <TooltipTrigger asChild>
169→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
170→                      onClick={() => onDownload(r.file_path!, r.filename)}>
171→                      <FileText className="h-3.5 w-3.5" />
172→                    </Button>
173→                  </TooltipTrigger>
174→                  <TooltipContent>Download</TooltipContent>
175→                </Tooltip>
176→              )}
177→              <Tooltip>
178→                <TooltipTrigger asChild>
179→                  <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-amber-500"
180→                    onClick={() => onDismiss(r.resume_id)}>
181→                    <Archive className="h-3.5 w-3.5" />
182→                  </Button>
183→                </TooltipTrigger>
184→                <TooltipContent>Archive</TooltipContent>
185→              </Tooltip>
186→            </TooltipProvider>
187→          </div>
188→        </TableCell>
189→      </TableRow>
190→
191→      {r.candidate_email && (
192→        <EmailOutreachDialog
193→          open={emailDialogOpen}
194→          onOpenChange={setEmailDialogOpen}
195→          candidateName={r.candidate_name || r.filename}
196→          candidateEmail={r.candidate_email}
197→          jobTitle={jobTitle || "Open Position"}
