409→    }
410→    const filesToRank = [...files];
411→    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
412→    setRanking(true); setRankingError(null);
413→    setRankingProgress(10); setScoredCount(0); setTotalToScore(filesToRank.length);
