446→  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
447→    if (!user) return [];
448→    const resumeIds: string[] = [];
449→    const failures: string[] = [];
450→    const skippedDupes: string[] = [];
451→
452→    // Fetch existing filenames for this job to prevent DB-level duplicates
453→    const { data: existingInDb } = await supabase
454→      .from("resumes")
455→      .select("filename")
456→      .eq("job_id", jobId);
457→    const dbFilenames = new Set((existingInDb ?? []).map((r: any) => r.filename.toLowerCase()));
458→
459→    for (const { file, name } of filesToUpload) {
460→      // Skip if this filename already exists in the job
461→      if (dbFilenames.has(name.toLowerCase())) {
462→        skippedDupes.push(name);
463→        continue;
464→      }
465→      try {
466→        const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
467→        const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
468→        if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
469→        const { data: resume, error: resumeError } = await supabase
470→          .from("resumes")
471→          .insert({ job_id: jobId, filename: name, file_path: filePath })
472→          .select("id")
473→          .single();
474→        if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
475→        resumeIds.push(resume.id);
476→        dbFilenames.add(name.toLowerCase()); // track within batch
477→      } catch (err) {
478→        console.error(`Upload failed for ${name}:`, err);
479→        failures.push(name);
480→      }
481→    }
482→    if (skippedDupes.length > 0) {
483→      toast.error(`Duplicate resume${skippedDupes.length > 1 ? "s" : ""} already uploaded: ${skippedDupes.join(", ")}`);
484→    }
485→    if (failures.length > 0) {
486→      toast.warning(`${failures.length} file(s) failed to upload: ${failures.join(", ")}`);
487→    }
488→    if (resumeIds.length === 0 && skippedDupes.length > 0) {
489→      throw new Error("All files are duplicates that were already uploaded to this job.");
490→    }
491→    if (resumeIds.length === 0) throw new Error("All file uploads failed. Please check your files and try again.");
492→    return resumeIds;
493→  };
