495→  const rankAndPoll = async (jobId: string, resumeIds: string[]) => {
496→    // Refresh auth session before invoking to prevent stale token errors
497→    await supabase.auth.refreshSession();
498→
499→    const { data: rankData, error: rankError } = await supabase.functions.invoke("rank-resumes", {
500→      body: { job_id: jobId, resume_ids: resumeIds },
501→    });
502→    if (rankError) {
503→      const err: any = new Error(rankError.message || "Ranking failed");
504→      err.status = 500;
505→      throw err;
506→    }
507→    if (rankData?.error) {
508→      const err: any = new Error(rankData.error);
509→      err.status = rankData.status || 500;
510→      throw err;
511→    }
512→    setRankingProgress(60);
513→
514→    for (let i = 0; i < 150; i++) {
515→      await new Promise((r) => setTimeout(r, 2000));
516→      // Stop polling if user switched to a different job
517→      if (activeJobRef.current !== jobId) return;
518→
519→      // Refresh auth session periodically to prevent token expiry during long polls
520→      if (i > 0 && i % 5 === 0) {
521→        try { await supabase.auth.refreshSession(); } catch {}
522→      }
523→
524→      try {
525→      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
526→      if (resumeProgress) {
527→        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
528→        setScoredCount(done);
529→        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
530→        setRankingProgress(Math.min(60 + pct, 95));
531→      }
532→
533→      const { data: jobData } = await supabase.from("jobs").select("status, processing_started_at").eq("id", jobId).single();
534→
535→      // Stuck-job detection: if processing for > 5 minutes
536→      if (jobData?.status === "processing" && jobData?.processing_started_at) {
537→        const elapsed = Date.now() - new Date(jobData.processing_started_at).getTime();
538→        if (elapsed > 5 * 60 * 1000) {
539→          setStuckJobDetected(true);
540→          setRanking(false);
541→          setRankingProgress(0);
542→          return;
543→        }
544→      }
545→
546→      if (jobData?.status === "completed") {
547→         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
548→         if (allResumes) {
549→           const allResumeIds = allResumes.map((r: any) => r.id);
550→            const { data: resultData } = await supabase
551→              .from("results")
552→              .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
553→              .in("resume_id", allResumeIds);
554→
555→            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
556→            const allMerged: Result[] = (resultData ?? []).map((r: any) => {
557→              const resume = resumeMap.get(r.resume_id);
558→              const parsed = resume?.parsed_json as any;
559→              return {
560→                ...r,
561→                overall_score: r.overall_score ?? 0,
562→                missing_skills: r.missing_skills ?? [],
563→                filename: resume?.filename ?? "Unknown",
564→                file_path: resume?.file_path ?? null,
565→                candidate_name: resume?.candidate_name ?? null,
566→                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
567→                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
568→                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
569→                parsed_json: resume?.parsed_json ?? null,
570→              };
571→            });
572→          // Deduplicate by resume_id — keep highest score
573→          const deduped = new Map<string, Result>();
574→          for (const r of allMerged) {
575→            const existing = deduped.get(r.resume_id);
576→            if (!existing || r.overall_score > existing.overall_score) {
577→              deduped.set(r.resume_id, r);
578→            }
579→          }
580→          const merged = Array.from(deduped.values());
581→          merged.sort((a, b) => b.overall_score - a.overall_score);
582→          setResults(merged);
583→        }
584→        setStuckJobDetected(false);
585→        setRankingProgress(100);
586→        await refreshProfile();
587→        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);
588→        return;
589→      }
590→      if (jobData?.status === "failed") throw new Error("Ranking failed on server");
591→      } catch (pollErr) {
592→        console.warn(`Poll iteration ${i} failed:`, pollErr);
593→        // On final iteration, rethrow; otherwise retry on next poll
594→        if (i >= 149) throw pollErr;
595→      }
596→    }
597→    throw new Error("Ranking timed out");
598→  };
