 37→const CATEGORIES = [
 38→  "Feature",
 39→  "Improvement",
 40→  "Integration",
 41→  "UI & Design",
 42→  "Data & Export",
 43→  "API & Integration",
 44→  "Search & Filters",
 45→  "General",
 46→];
 47→
 48→const STATUS_TABS = [
 49→  { value: "all", label: "All" },
