 53→  { value: "done", label: "Done" },
 54→];
 55→
 56→const STATUS_STYLES: Record<string, { label: string; dot: string; bg: string; text: string }> = {
 57→  submitted: { label: "Under Review", dot: "bg-amber-500", bg: "bg-amber-50 dark:bg-amber-950/30", text: "text-amber-700 dark:text-amber-400" },
 58→  planned: { label: "Planned", dot: "bg-emerald-600", bg: "bg-emerald-50 dark:bg-emerald-950/30", text: "text-emerald-700 dark:text-emerald-400" },
 59→  in_progress: { label: "In Progress", dot: "bg-blue-500", bg: "bg-blue-50 dark:bg-blue-950/30", text: "text-blue-700 dark:text-blue-400" },
 60→  done: { label: "Done", dot: "bg-stone-600", bg: "bg-stone-100 dark:bg-stone-800/40", text: "text-stone-700 dark:text-stone-300" },
