 67→function StatusBadge({ status }: { status: string }) {
 68→  const s = getStatusStyle(status);
 69→  return (
 70→    <span className={`inline-flex items-center gap-1.5 text-xs font-medium px-2.5 py-0.5 rounded-full ${s.bg} ${s.text}`}>
