import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Briefcase, ChevronDown, ChevronUp } from "lucide-react";

interface Role {
  title?: string;
  company?: string;
  start?: string;
  end?: string;
  description?: string;
  type?: string;
  employment_type?: string;
}

interface ExperiencePanelProps {
  parsedJson: any;
  matchedMustHaves?: string[];
}

/* ── Date helpers ─────────────────────────────────────────── */

/** Parse a date string into a rough Date (month-level) */
const parseDate = (dateStr?: any): Date | null => {
  if (dateStr == null) return null;
  const s = String(dateStr).trim();

  // Check "present/current"
  if (/present|current|now/i.test(s)) return new Date();

  // Try "MMM YYYY" or "MM/YYYY" or "YYYY"
  const monthNames: Record<string, number> = {
    jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
    jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11,
  };

  // "Jan 2023", "January 2023", "Jun 2022"
  const mmmYyyy = s.match(/([a-zA-Z]+)\s*(\d{4})/);
  if (mmmYyyy) {
    const mo = monthNames[mmmYyyy[1].slice(0, 3).toLowerCase()];
    if (mo !== undefined) return new Date(parseInt(mmmYyyy[2]), mo);
  }

  // "2023-01", "01/2023"
  const numDate = s.match(/(\d{1,2})[\/\-](\d{4})/);
  if (numDate) return new Date(parseInt(numDate[2]), parseInt(numDate[1]) - 1);

  // "2023"
  const yearOnly = s.match(/\b(19|20)\d{2}\b/);
  if (yearOnly) return new Date(parseInt(yearOnly[0]), 0);

  return null;
};

const isCurrent = (dateStr?: any): boolean => {
  if (dateStr == null) return false;
  return /present|current|now/i.test(String(dateStr));
};

/** Compute months between two dates */
const monthsBetween = (start: Date, end: Date): number => {
  return Math.max(0, (end.getFullYear() - start.getFullYear()) * 12 + (end.getMonth() - start.getMonth()));
};

/** Format months as "X yrs Y mos" or "X mos" */
const formatDuration = (months: number): string => {
  if (months <= 0) return "";
  const yrs = Math.floor(months / 12);
  const mos = months % 12;
  if (yrs === 0) return `${mos} mos`;
  if (mos === 0) return `${yrs} yr${yrs !== 1 ? "s" : ""}`;
  return `${yrs} yr${yrs !== 1 ? "s" : ""} ${mos} mos`;
};

/** Format date as "MMM YYYY" */
const formatDate = (d: Date): string => {
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return `${months[d.getMonth()]} ${d.getFullYear()}`;
};

/** Get employment type label */
const getEmpType = (role: Role): { label: string; cls: string } | null => {
  const t = (role.employment_type || role.type || "").toLowerCase();
  if (t.includes("intern")) return { label: "Internship", cls: "bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800" };
  if (t.includes("contract") || t.includes("freelance")) return { label: "Contract", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
  if (t.includes("part")) return { label: "Part-time", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
  if (t.includes("full") || t === "") return { label: "Full-time", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  return { label: t, cls: "bg-muted text-muted-foreground border-border" };
};

/** JD relevance tag */
type RelevanceTag = "jd_relevant" | "partially_relevant" | "low_relevance";
const RELEVANCE: Record<RelevanceTag, { label: string; cls: string }> = {
  jd_relevant: { label: "JD Relevant", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
  partially_relevant: { label: "Partially Relevant", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" },
  low_relevance: { label: "Low Relevance", cls: "bg-muted/60 text-muted-foreground border-border" },
};

/* ── Component ────────────────────────────────────────────── */

const ExperiencePanel = ({ parsedJson, matchedMustHaves }: ExperiencePanelProps) => {
  const [showDetail, setShowDetail] = useState(false);
  const rawRoles = parsedJson?.roles_with_dates ?? parsedJson?.experience;
  const roles: Role[] = Array.isArray(rawRoles) ? rawRoles : [];
  const matchedLower = Array.isArray(matchedMustHaves) ? matchedMustHaves.map((m) => String(m).toLowerCase()) : [];

  // Parse dates for each role
  const parsed = roles.map((role) => {
    const startDate = parseDate(role.start);
    const endDate = parseDate(role.end) || (isCurrent(role.end) ? new Date() : null);
    const months = startDate && endDate ? monthsBetween(startDate, endDate) : 0;
    const empType = getEmpType(role);
    const isInternship = empType?.label === "Internship";
    const isCurrentRole = isCurrent(role.end);

    // JD relevance: check if role title/description matches any must-have
    const combined = `${role.title || ""} ${role.description || ""} ${role.company || ""}`.toLowerCase();
    let relevance: RelevanceTag = "low_relevance";
    const fullMatch = matchedLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.filter((w) => combined.includes(w)).length >= Math.max(1, Math.floor(words.length * 0.5));
    });
    if (fullMatch) relevance = "jd_relevant";
    else if (matchedLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.some((w) => combined.includes(w));
    })) relevance = "partially_relevant";

    return { ...role, startDate, endDate, months, empType, isInternship, isCurrentRole, relevance };
  });

  // Stat pills
  const totalMonths = parsed.reduce((sum, r) => sum + r.months, 0);
  const fullTimeMonths = parsed.filter((r) => !r.isInternship).reduce((sum, r) => sum + r.months, 0);
  const internMonths = parsed.filter((r) => r.isInternship).reduce((sum, r) => sum + r.months, 0);

  // Gap detection between consecutive roles
  const gaps: { afterIndex: number; months: number }[] = [];
  for (let i = 0; i < parsed.length - 1; i++) {
    const prev = parsed[i];
    const next = parsed[i + 1];
    if (prev.startDate && next.endDate) {
      const gapMonths = monthsBetween(next.endDate, prev.startDate);
      if (gapMonths >= 3) gaps.push({ afterIndex: i, months: gapMonths });
    }
  }
  const gapMap = new Map(gaps.map((g) => [g.afterIndex, g]));

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      {/* Header with stat pills */}
      <div className="flex items-center gap-2 flex-wrap">
        <div className="w-6 h-6 rounded bg-purple-500/10 flex items-center justify-center">
          <Briefcase className="h-3.5 w-3.5 text-purple-500" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Experience</h4>
        <div className="flex items-center gap-1 ml-auto flex-wrap">
          {totalMonths > 0 && (
            <Badge variant="outline" className="text-[11px] font-semibold">
              {formatDuration(totalMonths)} <span className="text-muted-foreground font-normal ml-0.5">Total</span>
            </Badge>
          )}
          {fullTimeMonths > 0 && internMonths > 0 && (
            <>
              <Badge variant="outline" className="text-[11px] bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800">
                {formatDuration(fullTimeMonths)} <span className="font-normal ml-0.5">Full-time</span>
              </Badge>
              <Badge variant="outline" className="text-[11px] bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800">
                {formatDuration(internMonths)} <span className="font-normal ml-0.5">Internship</span>
              </Badge>
            </>
          )}
        </div>
      </div>

      {/* Roles timeline */}
      {parsed.length > 0 ? (
        <div className="space-y-0">
          {parsed.slice(0, showDetail ? undefined : 4).map((role, i) => {
            const gap = gapMap.get(i);
            const dotOpacity = "bg-muted-foreground/40";
            const rel = RELEVANCE[role.relevance];

            return (
              <div key={i}>
                <div className="flex gap-2 py-1.5">
                  {/* Timeline dot + line */}
                  <div className="flex flex-col items-center mt-1.5">
                    <div className={`w-2 h-2 rounded-full shrink-0 ${dotOpacity}`} />
                    {i < parsed.length - 1 && <div className="w-px flex-1 bg-border mt-1" />}
                  </div>

                  {/* Role content */}
                  <div className="flex-1 min-w-0 space-y-0.5">
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <p className="text-xs font-semibold text-foreground leading-tight">
                        {role.title || "Untitled Role"}
                      </p>
                      {role.empType && (
                        <span className={`text-[8px] font-semibold uppercase px-1.5 py-0.5 rounded border ${role.empType.cls}`}>
                          {role.empType.label}
                        </span>
                      )}
                    </div>
                    {role.company && (
                      <p className="text-[11px] text-muted-foreground">{role.company}</p>
                    )}
                    <div className="flex items-center gap-1.5 flex-wrap">
                      {role.startDate && (
                        <span className="text-[11px] text-muted-foreground">
                          {formatDate(role.startDate)} – {role.isCurrentRole ? "Present" : role.endDate ? formatDate(role.endDate) : ""}
                        </span>
                      )}
                      {role.months > 0 && (
                        <span className="text-[11px] font-medium text-emerald-600 dark:text-emerald-400">
                          {formatDuration(role.months)}
                        </span>
                      )}
                    </div>
                    {role.relevance !== "low_relevance" && (
                      <Badge variant="outline" className={`text-[11px] mt-0.5 ${rel.cls}`}>
                        {rel.label}
                      </Badge>
                    )}
                    {role.relevance === "low_relevance" && (
                      <span className="text-[11px] text-muted-foreground/60">Low Relevance</span>
                    )}
                  </div>
                </div>

                {/* Career gap flag */}
                {gap && (
                  <div className="flex items-center gap-2 pl-4 py-1">
                    <div className="flex-1 h-px bg-amber-300 dark:bg-amber-700" />
                    <span className="text-[11px] font-medium text-amber-600 dark:text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded-full border border-amber-200 dark:border-amber-800">
                      {gap.months} mo gap
                    </span>
                    <div className="flex-1 h-px bg-amber-300 dark:bg-amber-700" />
                  </div>
                )}
              </div>
            );
          })}
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">No experience data available</p>
      )}

      {/* Footer */}
      {parsed.length > 0 && (
        <div className="flex items-center justify-between pt-1 border-t border-border">
          <span className="text-[11px] text-muted-foreground">
            {parsed.length} role{parsed.length !== 1 ? "s" : ""}
            {gaps.length > 0 ? ` · ${gaps.length} gap${gaps.length !== 1 ? "s" : ""}` : ""}
          </span>
          {parsed.length > 4 && (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-[11px] text-muted-foreground hover:text-foreground gap-1"
              onClick={() => setShowDetail(!showDetail)}
            >
              {showDetail ? "Show less" : "See full detail"}
              {showDetail ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
            </Button>
          )}
        </div>
      )}
    </div>
  );
};

export default ExperiencePanel;

import { Fragment } from "react";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import { XCircle } from "lucide-react";
import { STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
import { format } from "date-fns";

interface StageTrackerProps {
  currentStage: HiringStage;
  updatedAt?: string | null;
  onStageChange: (stage: HiringStage) => void;
  disabled?: boolean;
}

const STAGE_LABELS: Record<string, string> = {
  applied: "Applied",
  screened: "Screened",
  interview: "Interview",
  offer: "Offer",
  hired: "Hired",
};

const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled }: StageTrackerProps) => {
  const currentIndex = currentStage === "rejected" ? -1 : STAGE_ORDER.indexOf(currentStage);
  const isRejected = currentStage === "rejected";

  return (
    <div className="flex items-center gap-3 py-1">
      <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>

      {/* Dots + connectors + labels */}
      <div className="flex-1 min-w-0">
        {/* Top row: dots and connectors */}
        <div className="flex items-center">
          {STAGE_ORDER.map((stage, i) => {
            const isCompleted = !isRejected && i < currentIndex;
            const isCurrent = !isRejected && i === currentIndex;
            const isUpcoming = isRejected || i > currentIndex;

            return (
              <Fragment key={stage}>
                <TooltipProvider delayDuration={150}>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <button
                        disabled={disabled}
                        onClick={(e) => { e.stopPropagation(); onStageChange(stage); }}
                        className={cn(
                          "relative w-6 h-6 rounded-full flex items-center justify-center text-[11px] font-bold transition-all duration-150 shrink-0",
                          "focus:outline-none focus-visible:ring-2 focus-visible:ring-primary/40",
                          isCompleted && "bg-emerald-500 text-white dark:bg-emerald-600 shadow-sm",
                          isCurrent && "bg-primary text-primary-foreground ring-2 ring-primary/30 shadow-sm",
                          isUpcoming && "bg-muted border border-border text-muted-foreground",
                          !disabled && "cursor-pointer hover:scale-110 hover:shadow",
                          disabled && "cursor-default"
                        )}
                      >
                        {isCompleted ? "✓" : i + 1}
                      </button>
                    </TooltipTrigger>
                    <TooltipContent className="text-xs">
                      {isCompleted
                        ? `${STAGE_LABELS[stage]} — done`
                        : isCurrent
                        ? `${STAGE_LABELS[stage]} — current stage`
                        : `Move to ${STAGE_LABELS[stage]}`}
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>

                {i < STAGE_ORDER.length - 1 && (
                  <div className={cn(
                    "h-px flex-1 min-w-[16px] max-w-[48px] transition-colors duration-200 shrink-0",
                    i < currentIndex && !isRejected ? "bg-emerald-500" : "bg-border"
                  )} />
                )}
              </Fragment>
            );
          })}
        </div>

        {/* Bottom row: labels aligned under each dot */}
        <div className="flex items-start mt-1.5">
          {STAGE_ORDER.map((stage, i) => {
            const isCompleted = !isRejected && i < currentIndex;
            const isCurrent = !isRejected && i === currentIndex;

            return (
              <Fragment key={stage}>
                <span className={cn(
                  "w-6 text-center text-[8px] leading-none",
                  isCompleted && "text-emerald-600 dark:text-emerald-400",
                  isCurrent && "text-primary font-semibold",
                  !isCompleted && !isCurrent && "text-muted-foreground"
                )}>
                  {STAGE_LABELS[stage]}
                </span>
                {i < STAGE_ORDER.length - 1 && (
                  <div className="flex-1 min-w-[16px] max-w-[48px]" />
                )}
              </Fragment>
            );
          })}
        </div>
      </div>

      {/* Reject button — visible on all screen sizes */}
      <TooltipProvider delayDuration={150}>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              disabled={disabled}
              className={cn(
                "h-7 w-7 shrink-0",
                isRejected
                  ? "text-destructive bg-destructive/10 hover:bg-destructive/20"
                  : "text-muted-foreground/40 hover:text-destructive hover:bg-destructive/10"
              )}
              onClick={(e) => { e.stopPropagation(); onStageChange("rejected"); }}
            >
              <XCircle className="h-3.5 w-3.5" />
            </Button>
          </TooltipTrigger>
          <TooltipContent className="text-xs">
            {isRejected ? "Click any stage to restore" : "Reject candidate"}
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>

      {/* Rejected badge */}
      {isRejected && (
        <Badge variant="destructive" className="text-[11px] shrink-0">Rejected</Badge>
      )}

      {/* Updated timestamp */}
      {updatedAt && (() => {
        try {
          return (
            <span className="text-[11px] text-muted-foreground shrink-0">
              Updated {format(new Date(updatedAt), "MMM d")}
            </span>
          );
        } catch {
          return null;
        }
      })()}
    </div>
  );
};

export default StageTracker;

import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { GraduationCap, BookOpen, School, Award, ChevronDown, ChevronUp, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";

interface Education {
  degree?: string;
  institution?: string;
  year?: string;
}

interface EducationPanelProps {
  parsedJson: any;
  matchedMustHaves?: string[];
  missingMustHaves?: string[];
}

/* ── Helpers ──────────────────────────────────────────────── */

/** Extract the most recent 4-digit year from a date string */
const extractYear = (yearStr?: string | number): number | null => {
  if (yearStr == null) return null;
  if (typeof yearStr === "number") return yearStr >= 1900 && yearStr <= 2100 ? yearStr : null;
  const match = String(yearStr).match(/\b(19|20)\d{2}\b/g);
  if (!match) return null;
  return Math.max(...match.map(Number));
};

/** Year pill colour: green if recent (≤3 yrs), amber if old (5+ yrs), grey otherwise */
const getYearVariant = (year: number): { cls: string } => {
  const age = new Date().getFullYear() - year;
  if (age <= 3) return { cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  if (age >= 5) return { cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
  return { cls: "bg-muted text-muted-foreground border-border" };
};

/** Infer education level from degree name for icon + rank */
type EduLevel = "doctorate" | "masters" | "bachelors" | "diploma" | "higher_secondary" | "secondary" | "other";

const inferLevel = (degree: string): EduLevel => {
  const d = degree.toLowerCase();
  if (d.includes("phd") || d.includes("doctorate") || d.includes("d.phil")) return "doctorate";
  if (d.includes("master") || d.includes("mba") || d.includes("m.sc") || d.includes("m.tech") || d.includes("m.e.") || d.includes("m.a.") || d.includes("msc") || d.includes("m.com")) return "masters";
  if (d.includes("bachelor") || d.includes("b.sc") || d.includes("b.tech") || d.includes("b.e.") || d.includes("b.a.") || d.includes("bsc") || d.includes("b.com") || d.includes("bba") || d.includes("bca")) return "bachelors";
  // Check secondary/higher_secondary BEFORE diploma — "High School Diploma" should be secondary, not diploma
  if (d.includes("higher secondary") || d.includes("12th") || d.includes("hsc") || d.includes("intermediate") || d.includes("a-level") || d.includes("senior secondary")) return "higher_secondary";
  if (d.includes("secondary") || d.includes("10th") || d.includes("ssc") || d.includes("o-level") || d.includes("high school") || d.includes("matriculation")) return "secondary";
  if (d.includes("diploma") || d.includes("certificate") || d.includes("pgd") || d.includes("post graduate diploma")) return "diploma";
  return "other";
};

const LEVEL_ICON: Record<EduLevel, typeof GraduationCap> = {
  doctorate: Award,
  masters: GraduationCap,
  bachelors: BookOpen,
  diploma: School,
  higher_secondary: School,
  secondary: School,
  other: GraduationCap,
};

const LEVEL_RANK: Record<EduLevel, { label: string; cls: string }> = {
  doctorate: { label: "Research", cls: "bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800" },
  masters: { label: "Specialised", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
  bachelors: { label: "Ranked", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" },
  diploma: { label: "Specialised", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
  higher_secondary: { label: "Tier 2", cls: "bg-muted text-muted-foreground border-border" },
  secondary: { label: "Secondary", cls: "bg-muted text-muted-foreground border-border" },
  other: { label: "Other", cls: "bg-muted text-muted-foreground border-border" },
};

/** Is this a low-relevance qualification? (secondary school etc.) */
const isLowRelevance = (level: EduLevel): boolean =>
  level === "secondary" || level === "higher_secondary";

/** Match score label */
const getScoreLabel = (score: number): { text: string; cls: string } => {
  if (score >= 75) return { text: "Strong", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  if (score >= 50) return { text: "Good", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
  if (score >= 25) return { text: "Partial", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
  return { text: "Weak", cls: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800" };
};

type RelevanceTag = "jd_match" | "relevant" | "gap" | "low_relevance";
const RELEVANCE_CLS: Record<RelevanceTag, string> = {
  jd_match: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800",
  relevant: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800",
  gap: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800",
  low_relevance: "bg-muted/60 text-muted-foreground border-border",
};
const RELEVANCE_LABEL: Record<RelevanceTag, string> = {
  jd_match: "JD Match",
  relevant: "Relevant",
  gap: "Gap",
  low_relevance: "Low relevance",
};

/* ── Component ────────────────────────────────────────────── */

const EducationPanel = ({ parsedJson, matchedMustHaves, missingMustHaves }: EducationPanelProps) => {
  const [showDetail, setShowDetail] = useState(false);
  const education: Education[] = Array.isArray(parsedJson?.education) ? parsedJson.education : [];
  const certifications: string[] = Array.isArray(parsedJson?.certifications) ? parsedJson.certifications : [];
  const matchedLower = (Array.isArray(matchedMustHaves) ? matchedMustHaves : []).map((m) => String(m).toLowerCase());
  const missingLower = (Array.isArray(missingMustHaves) ? missingMustHaves : []).map((m) => String(m).toLowerCase());

  // Classify each education entry
  const classified = education.map((edu) => {
    const degree = edu.degree || "";
    const institution = edu.institution || "";
    const combined = `${degree} ${institution}`.toLowerCase();
    const level = inferLevel(degree);
    const year = extractYear(edu.year);
    const Icon = LEVEL_ICON[level];
    const rank = LEVEL_RANK[level];

    let tag: RelevanceTag = isLowRelevance(level) ? "low_relevance" : "relevant";
    const isMatched = matchedLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.some((w) => combined.includes(w));
    });
    if (isMatched) tag = "jd_match";

    return { ...edu, degree, institution, level, year, Icon, rank, tag };
  });

  // Stats
  const jdMatchCount = classified.filter((c) => c.tag === "jd_match").length;
  const relevantCount = classified.filter((c) => c.tag === "relevant").length;
  const useful = classified.filter((c) => c.tag !== "low_relevance");

  // Education gaps — missing must-haves related to education
  const educationKeywords = ["degree", "education", "qualification", "certified", "certificate", "diploma", "bachelor", "master", "phd", "analytics", "marketing", "design", "engineering", "computer", "science", "mba"];
  const educationGaps = missingLower
    .filter((m) => educationKeywords.some((k) => m.includes(k)) || m.includes("formal"))
    .map((m) => {
      const original = (missingMustHaves || []).find((o) => o.toLowerCase() === m) || m;
      const isCritical = matchedLower.length > 0 || missingLower.indexOf(m) < missingLower.length / 2;
      return { text: original, severity: isCritical ? "critical" as const : "preferred" as const };
    });
  const gapCount = educationGaps.length;

  // Match score: percentage of useful qualifications vs total, weighted by relevance
  const matchScore = classified.length > 0
    ? Math.round((useful.length / classified.length) * (jdMatchCount > 0 ? 90 : 65) + (jdMatchCount > 0 ? 10 : 0))
    : 0;
  const scoreLabel = getScoreLabel(matchScore);

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      {/* ── Header with stat pills ─────────────────────────── */}
      <div className="flex items-center gap-2 flex-wrap">
        <div className="w-6 h-6 rounded bg-score-education/10 flex items-center justify-center">
          <GraduationCap className="h-3.5 w-3.5 text-score-education" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Education</h4>
        <div className="flex items-center gap-1 ml-auto flex-wrap">
          {jdMatchCount > 0 && (
            <Badge variant="outline" className={`text-[11px] ${RELEVANCE_CLS.jd_match}`}>
              {jdMatchCount} JD Match
            </Badge>
          )}
          {relevantCount > 0 && (
            <Badge variant="outline" className={`text-[11px] ${RELEVANCE_CLS.relevant}`}>
              {relevantCount} Relevant
            </Badge>
          )}
          {gapCount > 0 && (
            <Badge variant="outline" className={`text-[11px] ${RELEVANCE_CLS.gap}`}>
              {gapCount} Gap
            </Badge>
          )}
        </div>
      </div>

      {/* ── Match score bar ────────────────────────────────── */}
      {classified.length > 0 && (
        <div className="space-y-1.5">
          <span className="text-[11px] uppercase tracking-wider text-muted-foreground font-medium">Education Match Score</span>
          <div className="flex items-center gap-3">
            <span className="text-xl font-bold tabular-nums text-foreground">{matchScore}%</span>
            <div className="flex-1 space-y-1">
              <div className="flex items-center gap-1.5">
                <Badge variant="outline" className={`text-[11px] ${scoreLabel.cls}`}>{scoreLabel.text}</Badge>
                <span className="text-[11px] text-muted-foreground">AI estimated · {useful.length} of {classified.length} useful</span>
              </div>
              <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
                <div
                  className="h-full rounded-full bg-score-education transition-all"
                  style={{ width: `${Math.min(matchScore, 100)}%` }}
                />
              </div>
              <div className="flex justify-between text-[8px] text-muted-foreground/50">
                <span>Weak</span><span>Partial</span><span>Good</span><span>Strong</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── Qualifications list ────────────────────────────── */}
      {classified.length > 0 ? (
        <div className="space-y-1">
          <span className="text-[11px] uppercase tracking-wider text-muted-foreground font-medium">Qualifications</span>
          <div className="space-y-2">
            {classified.slice(0, 4).map((edu, i) => {
              const lowRel = edu.tag === "low_relevance";
              return (
                <div key={i} className={`flex items-start gap-2 ${lowRel ? "opacity-40" : ""}`}>
                  <edu.Icon className={`h-3.5 w-3.5 shrink-0 mt-0.5 ${lowRel ? "text-muted-foreground/60" : "text-muted-foreground"}`} />
                  <div className="flex-1 min-w-0 space-y-0.5">
                    <p className={`text-xs font-medium leading-tight ${lowRel ? "text-muted-foreground" : "text-foreground"}`}>
                      {edu.degree || "Degree"}
                    </p>
                    {edu.institution && (
                      <p className="text-[11px] text-muted-foreground">{edu.institution}</p>
                    )}
                    <div className="flex items-center gap-1.5 flex-wrap">
                      {edu.year && String(edu.year) !== "" && (() => {
                        const yearNum = edu.year ? extractYear(edu.year) : null;
                        const yearVariant = yearNum ? getYearVariant(yearNum) : null;
                        return (
                          <span className={`text-[11px] font-medium px-1.5 py-0.5 rounded border ${yearVariant?.cls || "bg-muted text-muted-foreground border-border"}`}>
                            {yearNum || edu.year}
                          </span>
                        );
                      })()}
                      {!lowRel && (
                        <span className={`text-[11px] font-medium px-1.5 py-0.5 rounded border ${edu.rank.cls}`}>
                          {edu.rank.label}
                        </span>
                      )}
                    </div>
                  </div>
                  <Badge variant="outline" className={`text-[11px] shrink-0 mt-0.5 ${RELEVANCE_CLS[edu.tag]}`}>
                    {RELEVANCE_LABEL[edu.tag]}
                  </Badge>
                </div>
              );
            })}
            {classified.length > 4 && (
              <p className="text-[11px] text-muted-foreground">+{classified.length - 4} more</p>
            )}
          </div>
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">No education data available</p>
      )}

      {/* ── Gaps — Hiring Risk ─────────────────────────────── */}
      {educationGaps.length > 0 && (
        <div className="space-y-1.5">
          <span className="text-[11px] uppercase tracking-wider text-destructive font-medium flex items-center gap-1">
            <AlertTriangle className="h-3 w-3" /> Gaps — Hiring Risk
          </span>
          <div className="space-y-1.5">
            {educationGaps.map((gap, i) => (
              <div
                key={i}
                className={`text-[11px] px-2.5 py-1.5 rounded-md border flex items-center justify-between gap-2 ${
                  gap.severity === "critical"
                    ? "bg-red-500/10 text-red-700 border-red-200 dark:text-red-400 dark:border-red-800"
                    : "bg-amber-500/10 text-amber-700 border-amber-200 dark:text-amber-400 dark:border-amber-800"
                }`}
              >
                <span className="font-medium">{gap.text}</span>
                <Badge variant="outline" className={`text-[8px] shrink-0 uppercase ${
                  gap.severity === "critical"
                    ? "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800"
                    : "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800"
                }`}>
                  {gap.severity}
                </Badge>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Footer: certifications + detail toggle ─────────── */}
      {(certifications.length > 0 || classified.length > 0) && (
        <div className="flex items-center justify-between pt-1 border-t border-border">
          <span className="text-[11px] text-muted-foreground">
            {certifications.length > 0
              ? `${certifications.length} cert${certifications.length !== 1 ? "s" : ""} available`
              : "No certifications"}
          </span>
          {(certifications.length > 0) && (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-[11px] text-muted-foreground hover:text-foreground gap-1"
              onClick={() => setShowDetail(!showDetail)}
            >
              See full detail {showDetail ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
            </Button>
          )}
        </div>
      )}

      {/* ── Expanded certifications ────────────────────────── */}
      {showDetail && certifications.length > 0 && (
        <div className="space-y-1">
          <span className="text-[11px] uppercase tracking-wider text-muted-foreground font-medium">Certifications</span>
          <div className="flex flex-wrap gap-1">
            {certifications.map((cert, i) => (
              <Badge key={i} variant="outline" className="text-[11px]">{cert}</Badge>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default EducationPanel;

import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { GraduationCap, BookOpen, School, Award, ChevronDown, ChevronUp, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";

interface Education {
  degree?: string;
  institution?: string;
  year?: string;
}

interface EducationPanelProps {
  parsedJson: any;
  matchedMustHaves?: string[];
  missingMustHaves?: string[];
}

/* ── Helpers ──────────────────────────────────────────────── */

/** Extract the most recent 4-digit year from a date string */
const extractYear = (yearStr?: string | number): number | null => {
  if (yearStr == null) return null;
  if (typeof yearStr === "number") return yearStr >= 1900 && yearStr <= 2100 ? yearStr : null;
  const match = String(yearStr).match(/\b(19|20)\d{2}\b/g);
  if (!match) return null;
  return Math.max(...match.map(Number));
};

/** Year pill colour: green if recent (≤3 yrs), amber if old (5+ yrs), grey otherwise */
const getYearVariant = (year: number): { cls: string } => {
  const age = new Date().getFullYear() - year;
  if (age <= 3) return { cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  if (age >= 5) return { cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
  return { cls: "bg-muted text-muted-foreground border-border" };
};

/** Infer education level from degree name for icon + rank */
type EduLevel = "doctorate" | "masters" | "bachelors" | "diploma" | "higher_secondary" | "secondary" | "other";

const inferLevel = (degree: string): EduLevel => {
  const d = degree.toLowerCase();
  if (d.includes("phd") || d.includes("doctorate") || d.includes("d.phil")) return "doctorate";
  if (d.includes("master") || d.includes("mba") || d.includes("m.sc") || d.includes("m.tech") || d.includes("m.e.") || d.includes("m.a.") || d.includes("msc") || d.includes("m.com")) return "masters";
  if (d.includes("bachelor") || d.includes("b.sc") || d.includes("b.tech") || d.includes("b.e.") || d.includes("b.a.") || d.includes("bsc") || d.includes("b.com") || d.includes("bba") || d.includes("bca")) return "bachelors";
  // Check secondary/higher_secondary BEFORE diploma — "High School Diploma" should be secondary, not diploma
  if (d.includes("higher secondary") || d.includes("12th") || d.includes("hsc") || d.includes("intermediate") || d.includes("a-level") || d.includes("senior secondary")) return "higher_secondary";
  if (d.includes("secondary") || d.includes("10th") || d.includes("ssc") || d.includes("o-level") || d.includes("high school") || d.includes("matriculation")) return "secondary";
  if (d.includes("diploma") || d.includes("certificate") || d.includes("pgd") || d.includes("post graduate diploma")) return "diploma";
  return "other";
};

const LEVEL_ICON: Record<EduLevel, typeof GraduationCap> = {
  doctorate: Award,
  masters: GraduationCap,
  bachelors: BookOpen,
  diploma: School,
  higher_secondary: School,
  secondary: School,
  other: GraduationCap,
};

const LEVEL_RANK: Record<EduLevel, { label: string; cls: string }> = {
  doctorate: { label: "Research", cls: "bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800" },
  masters: { label: "Specialised", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
  bachelors: { label: "Ranked", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" },
  diploma: { label: "Specialised", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
  higher_secondary: { label: "Tier 2", cls: "bg-muted text-muted-foreground border-border" },
  secondary: { label: "Secondary", cls: "bg-muted text-muted-foreground border-border" },
  other: { label: "Other", cls: "bg-muted text-muted-foreground border-border" },
};

/** Is this a low-relevance qualification? (secondary school etc.) */
const isLowRelevance = (level: EduLevel): boolean =>
  level === "secondary" || level === "higher_secondary";

/** Match score label */
const getScoreLabel = (score: number): { text: string; cls: string } => {
  if (score >= 75) return { text: "Strong", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  if (score >= 50) return { text: "Good", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
  if (score >= 25) return { text: "Partial", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
  return { text: "Weak", cls: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800" };
};

type RelevanceTag = "jd_match" | "relevant" | "gap" | "low_relevance";
const RELEVANCE_CLS: Record<RelevanceTag, string> = {
  jd_match: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800",
  relevant: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800",
  gap: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800",
  low_relevance: "bg-muted/60 text-muted-foreground border-border",
};
const RELEVANCE_LABEL: Record<RelevanceTag, string> = {
  jd_match: "JD Match",
  relevant: "Relevant",
  gap: "Gap",
  low_relevance: "Low relevance",
};

/* ── Component ────────────────────────────────────────────── */

const EducationPanel = ({ parsedJson, matchedMustHaves, missingMustHaves }: EducationPanelProps) => {
  const [showDetail, setShowDetail] = useState(false);
  const education: Education[] = Array.isArray(parsedJson?.education) ? parsedJson.education : [];
  const certifications: string[] = Array.isArray(parsedJson?.certifications) ? parsedJson.certifications : [];
  const matchedLower = (Array.isArray(matchedMustHaves) ? matchedMustHaves : []).map((m) => String(m).toLowerCase());
  const missingLower = (Array.isArray(missingMustHaves) ? missingMustHaves : []).map((m) => String(m).toLowerCase());

  // Classify each education entry
  const classified = education.map((edu) => {
    const degree = edu.degree || "";
    const institution = edu.institution || "";
    const combined = `${degree} ${institution}`.toLowerCase();
    const level = inferLevel(degree);
    const year = extractYear(edu.year);
    const Icon = LEVEL_ICON[level];
    const rank = LEVEL_RANK[level];

    let tag: RelevanceTag = isLowRelevance(level) ? "low_relevance" : "relevant";
    const isMatched = matchedLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.some((w) => combined.includes(w));
    });
    if (isMatched) tag = "jd_match";

    return { ...edu, degree, institution, level, year, Icon, rank, tag };
  });

  // Stats
  const jdMatchCount = classified.filter((c) => c.tag === "jd_match").length;
  const relevantCount = classified.filter((c) => c.tag === "relevant").length;
  const useful = classified.filter((c) => c.tag !== "low_relevance");

  // Education gaps — missing must-haves related to education
  const educationKeywords = ["degree", "education", "qualification", "certified", "certificate", "diploma", "bachelor", "master", "phd", "analytics", "marketing", "design", "engineering", "computer", "science", "mba"];
  const educationGaps = missingLower
    .filter((m) => educationKeywords.some((k) => m.includes(k)) || m.includes("formal"))
    .map((m) => {
      const original = (missingMustHaves || []).find((o) => o.toLowerCase() === m) || m;
      const isCritical = matchedLower.length > 0 || missingLower.indexOf(m) < missingLower.length / 2;
      return { text: original, severity: isCritical ? "critical" as const : "preferred" as const };
    });
  const gapCount = educationGaps.length;

  // Match score: percentage of useful qualifications vs total, weighted by relevance
  const matchScore = classified.length > 0
    ? Math.round((useful.length / classified.length) * (jdMatchCount > 0 ? 90 : 65) + (jdMatchCount > 0 ? 10 : 0))
    : 0;
  const scoreLabel = getScoreLabel(matchScore);

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      {/* ── Header with stat pills ─────────────────────────── */}
      <div className="flex items-center gap-2 flex-wrap">
        <div className="w-6 h-6 rounded bg-score-education/10 flex items-center justify-center">
          <GraduationCap className="h-3.5 w-3.5 text-score-education" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Education</h4>
        <div className="flex items-center gap-1 ml-auto flex-wrap">
          {jdMatchCount > 0 && (
            <Badge variant="outline" className={`text-[11px] ${RELEVANCE_CLS.jd_match}`}>
              {jdMatchCount} JD Match
            </Badge>
          )}
          {relevantCount > 0 && (
            <Badge variant="outline" className={`text-[11px] ${RELEVANCE_CLS.relevant}`}>
              {relevantCount} Relevant
            </Badge>
          )}
          {gapCount > 0 && (
            <Badge variant="outline" className={`text-[11px] ${RELEVANCE_CLS.gap}`}>
              {gapCount} Gap
            </Badge>
          )}
        </div>
      </div>

      {/* ── Match score bar ────────────────────────────────── */}
      {classified.length > 0 && (
        <div className="space-y-1.5">
          <span className="text-[11px] uppercase tracking-wider text-muted-foreground font-medium">Education Match Score</span>
          <div className="flex items-center gap-3">
            <span className="text-xl font-bold tabular-nums text-foreground">{matchScore}%</span>
            <div className="flex-1 space-y-1">
              <div className="flex items-center gap-1.5">
                <Badge variant="outline" className={`text-[11px] ${scoreLabel.cls}`}>{scoreLabel.text}</Badge>
                <span className="text-[11px] text-muted-foreground">AI estimated · {useful.length} of {classified.length} useful</span>
              </div>
              <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
                <div
                  className="h-full rounded-full bg-score-education transition-all"
                  style={{ width: `${Math.min(matchScore, 100)}%` }}
                />
              </div>
              <div className="flex justify-between text-[11px] text-muted-foreground/50">
                <span>Weak</span><span>Partial</span><span>Good</span><span>Strong</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── Qualifications list ────────────────────────────── */}
      {classified.length > 0 ? (
        <div className="space-y-1">
          <span className="text-[11px] uppercase tracking-wider text-muted-foreground font-medium">Qualifications</span>
          <div className="space-y-2">
            {classified.slice(0, 4).map((edu, i) => {
              const lowRel = edu.tag === "low_relevance";
              return (
                <div key={i} className={`flex items-start gap-2 ${lowRel ? "opacity-40" : ""}`}>
                  <edu.Icon className={`h-3.5 w-3.5 shrink-0 mt-0.5 ${lowRel ? "text-muted-foreground/60" : "text-muted-foreground"}`} />
                  <div className="flex-1 min-w-0 space-y-0.5">
                    <p className={`text-xs font-medium leading-tight ${lowRel ? "text-muted-foreground" : "text-foreground"}`}>
                      {edu.degree || "Degree"}
                    </p>
                    {edu.institution && (
                      <p className="text-[11px] text-muted-foreground">{edu.institution}</p>
                    )}
                    <div className="flex items-center gap-1.5 flex-wrap">
                      {edu.year && String(edu.year) !== "" && (() => {
                        const yearNum = edu.year ? extractYear(edu.year) : null;
                        const yearVariant = yearNum ? getYearVariant(yearNum) : null;
                        return (
                          <span className={`text-[11px] font-medium px-1.5 py-0.5 rounded border ${yearVariant?.cls || "bg-muted text-muted-foreground border-border"}`}>
                            {yearNum || edu.year}
                          </span>
                        );
                      })()}
                      {!lowRel && (
                        <span className={`text-[11px] font-medium px-1.5 py-0.5 rounded border ${edu.rank.cls}`}>
                          {edu.rank.label}
                        </span>
                      )}
                    </div>
                  </div>
                  <Badge variant="outline" className={`text-[11px] shrink-0 mt-0.5 ${RELEVANCE_CLS[edu.tag]}`}>
                    {RELEVANCE_LABEL[edu.tag]}
                  </Badge>
                </div>
              );
            })}
            {classified.length > 4 && (
              <p className="text-[11px] text-muted-foreground">+{classified.length - 4} more</p>
            )}
          </div>
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">No education data available</p>
      )}

      {/* ── Gaps — Hiring Risk ─────────────────────────────── */}
      {educationGaps.length > 0 && (
        <div className="space-y-1.5">
          <span className="text-[11px] uppercase tracking-wider text-destructive font-medium flex items-center gap-1">
            <AlertTriangle className="h-3 w-3" /> Gaps — Hiring Risk
          </span>
          <div className="space-y-1.5">
            {educationGaps.map((gap, i) => (
              <div
                key={i}
                className={`text-[11px] px-2.5 py-1.5 rounded-md border flex items-center justify-between gap-2 ${
                  gap.severity === "critical"
                    ? "bg-red-500/10 text-red-700 border-red-200 dark:text-red-400 dark:border-red-800"
                    : "bg-amber-500/10 text-amber-700 border-amber-200 dark:text-amber-400 dark:border-amber-800"
                }`}
              >
                <span className="font-medium">{gap.text}</span>
                <Badge variant="outline" className={`text-[8px] shrink-0 uppercase ${
                  gap.severity === "critical"
                    ? "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800"
                    : "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800"
                }`}>
                  {gap.severity}
                </Badge>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Footer: certifications + detail toggle ─────────── */}
      {(certifications.length > 0 || classified.length > 0) && (
        <div className="flex items-center justify-between pt-1 border-t border-border">
          <span className="text-[11px] text-muted-foreground">
            {certifications.length > 0
              ? `${certifications.length} cert${certifications.length !== 1 ? "s" : ""} available`
              : "No certifications"}
          </span>
          {(certifications.length > 0) && (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-[11px] text-muted-foreground hover:text-foreground gap-1"
              onClick={() => setShowDetail(!showDetail)}
            >
              See full detail {showDetail ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
            </Button>
          )}
        </div>
      )}

      {/* ── Expanded certifications ────────────────────────── */}
      {showDetail && certifications.length > 0 && (
        <div className="space-y-1">
          <span className="text-[11px] uppercase tracking-wider text-muted-foreground font-medium">Certifications</span>
          <div className="flex flex-wrap gap-1">
            {certifications.map((cert, i) => (
              <Badge key={i} variant="outline" className="text-[11px]">{cert}</Badge>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default EducationPanel;

