import { CheckCircle2, XCircle } from "lucide-react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { Result } from "@/pages/Index";

interface JDAlignedPanelProps {
  result: Result;
}

type RecLevel = "success" | "secondary" | "warning" | "destructive";

const getRecommendation = (score: number, hardFit: boolean | undefined, isHeuristic: boolean): { text: string; label: string; variant: RecLevel } => {
  if (isHeuristic) return { text: "Needs full AI scoring for reliable recommendation", label: "Pending", variant: "warning" };
  if (score >= 70 && hardFit !== false) return { text: "Strong core fit, gaps are learnable", label: "Shortlist", variant: "success" };
  if (score >= 50 && hardFit !== false) return { text: "Decent match, review before interview", label: "Consider", variant: "secondary" };
  if (score >= 40) return { text: "Has strengths but missing critical items", label: "Review", variant: "warning" };
  return { text: "Significant gaps for this role", label: "Pass", variant: "destructive" };
};

const JDAlignedPanel = ({ result: r }: JDAlignedPanelProps) => {
  const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.map(String) : [];
  const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.map(String) : [];
  const strengths = Array.isArray(r.strengths_json) ? r.strengths_json.map(String) : [];
  const gaps = Array.isArray(r.gaps_json) ? r.gaps_json.map(String) : [];
  const confidence = r.confidence ?? 0;
  const interviewQs = Array.isArray(r.interview_questions) ? r.interview_questions.map(String) : [];
  const isHeuristic = r.scoring_version === "heuristic";
  const isInsufficient = r.scoring_version === "insufficient";

  if (isInsufficient) return null;

  const totalMustHave = matched.length + missing.length;
  const mustHavePercent = totalMustHave > 0 ? Math.round((matched.length / totalMustHave) * 100) : 0;

  const rawMatchedPref = r.explanation_json?.matched_preferred;
  const matchedPreferred: string[] = Array.isArray(rawMatchedPref) ? rawMatchedPref.map(String)
    : (isHeuristic ? [] : strengths.filter((s) => !matched.some((m) => s.toLowerCase().includes(m.toLowerCase()))));
  const rawMissingPref = r.explanation_json?.missing_preferred;
  const missingPreferred: string[] = Array.isArray(rawMissingPref) ? rawMissingPref.map(String)
    : (isHeuristic ? [] : gaps.filter((g) => !missing.some((m) => g.toLowerCase().includes(m.toLowerCase()))));
  const totalPreferred = matchedPreferred.length + missingPreferred.length;

  const rec = getRecommendation(r.overall_score, r.hard_fit, isHeuristic);

  if (totalMustHave === 0 && totalPreferred === 0 && !r.explanation_json?.why_ranked_here) return null;

  return (
    <Card>
      <CardHeader className="pb-3 px-5 pt-4 flex-row items-center justify-between gap-3 space-y-0 flex-wrap">
        <div className="flex items-center gap-3">
          <h4 className="text-sm font-medium text-foreground">JD Alignment</h4>
          {totalMustHave > 0 && (
            <span className="text-sm text-muted-foreground tabular-nums">{mustHavePercent}% match</span>
          )}
        </div>
        <div className="flex items-center gap-2">
          <Badge variant={rec.variant}>{rec.label}</Badge>
          {confidence > 0 && <Badge variant="outline" className="text-xs">{confidence}% confidence</Badge>}
        </div>
      </CardHeader>

      <CardContent className="px-5 pb-5 pt-0">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Must Have */}
          {totalMustHave > 0 && (
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <h5 className="text-xs font-medium text-muted-foreground">Must Have</h5>
                <span className="text-xs text-muted-foreground/60">{matched.length}/{totalMustHave}</span>
              </div>
              <div className="space-y-2">
                {matched.map((item, i) => (
                  <div key={`m-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                    <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                    <span className="text-foreground">{item}</span>
                  </div>
                ))}
                {missing.map((item, i) => (
                  <div key={`x-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                    <XCircle className="h-3.5 w-3.5 text-red-400 shrink-0 mt-0.5" />
                    <span className="text-muted-foreground">{item}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Preferred */}
          {totalPreferred > 0 && (
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <h5 className="text-xs font-medium text-muted-foreground">Preferred</h5>
                <span className="text-xs text-muted-foreground/60">{matchedPreferred.length}/{totalPreferred}</span>
              </div>
              <div className="space-y-2">
                {matchedPreferred.map((item, i) => (
                  <div key={`pm-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                    <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                    <span className="text-foreground">{item}</span>
                  </div>
                ))}
                {missingPreferred.map((item, i) => (
                  <div key={`px-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                    <XCircle className="h-3.5 w-3.5 text-red-400 shrink-0 mt-0.5" />
                    <span className="text-muted-foreground">{item}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* AI Insight */}
          <div className="space-y-3">
            <h5 className="text-xs font-medium text-muted-foreground">AI Insight</h5>

            {r.explanation_json?.why_ranked_here && (
              <p className="text-sm text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
            )}

            <p className="text-sm text-foreground leading-relaxed">{rec.text}</p>

            {interviewQs.length > 0 && (
              <div className="pt-2 border-t border-border space-y-1">
                <h6 className="text-xs text-muted-foreground font-medium">Interview focus</h6>
                <p className="text-sm text-muted-foreground leading-relaxed">{interviewQs[0]}</p>
              </div>
            )}

            {r.explanation_json?.key_tradeoffs && (
              <p className="text-xs text-muted-foreground/60 leading-relaxed">{r.explanation_json.key_tradeoffs}</p>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

export default JDAlignedPanel;

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { TableCell, TableRow } from "@/components/ui/table";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import { Phone, Mail, MapPin, FileText, Archive } from "lucide-react";
import { toast } from "sonner";
import type { Result } from "@/pages/Index";
import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
import type { HiringStage } from "@/hooks/useStageTracker";

interface CandidateRowProps {
  result: Result;
  index: number;
  isSelected: boolean;
  isActive: boolean;
  jobId?: string | null;
  jobTitle?: string | null;
  onSelect: (id: string) => void;
  onToggleSelect: (resumeId: string) => void;
  onDownload: (filePath: string, filename: string) => void;
  onDismiss: (resumeId: string) => void;
  formatCandidateName: (filename: string) => string;
  currentStage?: HiringStage | null;
  isDuplicate?: boolean;
}

const getScoreColor = (score: number) => {
  if (score >= 70) return "bg-score-skills";
  if (score >= 40) return "bg-warning";
  return "bg-destructive";
};

const getScoreTextColor = (score: number) => {
  if (score >= 70) return "text-score-skills";
  if (score >= 40) return "text-warning";
  return "text-destructive";
};

const STAGE_BADGE_CLASSES: Record<string, string> = {
  applied: "border-border bg-muted/50 text-muted-foreground",
  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
};

const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

const CandidateRow = ({
  result: r,
  index,
  isSelected,
  isActive,
  jobId,
  jobTitle,
  onSelect,
  onToggleSelect,
  onDownload,
  onDismiss,
  formatCandidateName,
  currentStage,
  isDuplicate,
}: CandidateRowProps) => {
  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;

  return (
    <>
      <TableRow
        className={`cursor-pointer transition-colors animate-in fade-in slide-in-from-bottom-1 duration-200 ${isActive ? "bg-primary/5 hover:bg-primary/5" : "hover:bg-muted/50"}`}
        style={{ animationDelay: `${Math.min(index * 40, 400)}ms`, animationFillMode: "backwards" }}
        onClick={() => !r.pending && onSelect(r.id)}
      >
        <TableCell onClick={(e) => e.stopPropagation()}>
          <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
        </TableCell>
        <TableCell className="text-center">
          {r.pending
            ? <span className="text-sm text-muted-foreground">—</span>
            : <span className="text-sm font-medium tabular-nums text-muted-foreground">{index + 1}</span>}
        </TableCell>
        <TableCell className="font-medium">
          <div className="flex flex-col gap-0.5">
            <div className="flex items-center gap-1.5 flex-wrap">
              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
              {isDuplicate && (
                <Badge variant="outline" className="text-[11px] px-1.5 py-0 border-orange-300 text-orange-600 bg-orange-50">
                  Duplicate
                </Badge>
              )}
              {!r.pending && currentStage && currentStage !== "applied" && (
                <Badge
                  variant="outline"
                  className={`text-[11px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
                >
                  {currentStage}
                </Badge>
              )}
            </div>
            {r.candidate_location && (
              <span className="flex items-center gap-1 text-xs text-muted-foreground">
                <MapPin className="h-3 w-3" /> {r.candidate_location}
              </span>
            )}
          </div>
        </TableCell>
        <TableCell>
          {r.pending ? (
            <Badge variant="outline" className="text-xs">Pending</Badge>
          ) : (
            <div className="flex items-center gap-2">
              <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
                <div
                  className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
                  style={{ width: `${Math.min(r.overall_score, 100)}%` }}
                />
              </div>
              <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
                {r.overall_score?.toFixed(0)}%
              </span>
            </div>
          )}
        </TableCell>
        <TableCell>
          <div className="flex flex-wrap items-center gap-1">
            {!r.pending && strength && (
              <Badge variant={strength.variant} className="text-[11px]">{strength.label}</Badge>
            )}
            {!r.pending && r.scoring_version === "heuristic" && (
              <span className="inline-flex items-center text-[11px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium">Quick</span>
            )}
          </div>
        </TableCell>
        <TableCell>
          <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
            <TooltipProvider delayDuration={300}>
              {r.candidate_phone && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
                      onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
                      <Phone className="h-3.5 w-3.5" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>{r.candidate_phone}</TooltipContent>
                </Tooltip>
              )}
              {r.candidate_email && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
                      onClick={() => setEmailDialogOpen(true)}>
                      <Mail className="h-3.5 w-3.5" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Email</TooltipContent>
                </Tooltip>
              )}
              {r.file_path && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
                      onClick={() => onDownload(r.file_path!, r.filename)}>
                      <FileText className="h-3.5 w-3.5" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Download</TooltipContent>
                </Tooltip>
              )}
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-amber-500"
                    onClick={() => onDismiss(r.resume_id)}>
                    <Archive className="h-3.5 w-3.5" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Archive</TooltipContent>
              </Tooltip>
            </TooltipProvider>
          </div>
        </TableCell>
      </TableRow>

      {r.candidate_email && (
        <EmailOutreachDialog
          open={emailDialogOpen}
          onOpenChange={setEmailDialogOpen}
          candidateName={r.candidate_name || r.filename}
          candidateEmail={r.candidate_email}
          jobTitle={jobTitle || "Open Position"}
          matchScore={Math.round(r.overall_score ?? 0)}
          resumeId={r.resume_id}
          jobId={jobId || ""}
        />
      )}
    </>
  );
};

export default CandidateRow;

