export default CandidateRow;

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Shield, Eye, EyeOff } from "lucide-react";

const ChangePasswordCard = () => {
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [saving, setSaving] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
      toast.error("Password too short — must be at least 6 characters.");
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error("Passwords don't match");
      return;
    }
    setSaving(true);
    const { error } = await supabase.auth.updateUser({ password: newPassword });
    if (error) {
      toast.error(error.message);
    } else {
      toast.success("Password updated");
      setNewPassword("");
      setConfirmPassword("");
    }
    setSaving(false);
  };

  const passwordsMatch = newPassword && confirmPassword && newPassword === confirmPassword;
  const passwordsMismatch = confirmPassword && newPassword !== confirmPassword;

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <Shield className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-base font-semibold text-foreground">Change Password</h3>
          <p className="text-xs text-muted-foreground">Update your account password.</p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5 space-y-4">
        <div className="space-y-2">
          <Label htmlFor="new-password" className="text-sm">New password</Label>
          <div className="relative">
            <Input
              id="new-password"
              type={showPassword ? "text" : "password"}
              placeholder="Min 6 characters"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="pr-10"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
            >
              {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
            </button>
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="confirm-password" className="text-sm">Confirm password</Label>
          <Input
            id="confirm-password"
            type={showPassword ? "text" : "password"}
            placeholder="Re-enter password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            className={passwordsMismatch ? "border-destructive focus-visible:ring-destructive" : passwordsMatch ? "border-primary/50 focus-visible:ring-primary" : ""}
          />
          {passwordsMismatch && (
            <p className="text-xs text-destructive">Passwords don't match.</p>
          )}
          {passwordsMatch && (
            <p className="text-xs text-primary">Passwords match ✓</p>
          )}
        </div>
        <Button
          onClick={handleChangePassword}
          disabled={saving || !newPassword || !passwordsMatch}
          className="w-full"
        >
          {saving ? "Updating…" : "Update password"}
        </Button>
      </CardContent>
    </Card>
  );
};

export default ChangePasswordCard;

import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { toast } from "sonner";
import { Copy, Mail, Check, ChevronDown, Info, RefreshCw, Loader2 } from "lucide-react";

const EmailInboxCard = () => {
  const { user, profile, refreshProfile } = useAuth();
  const [togglingEmail, setTogglingEmail] = useState(false);
  const [copied, setCopied] = useState(false);
  const [howItWorksOpen, setHowItWorksOpen] = useState(false);
  const [regenerating, setRegenerating] = useState(false);

  const handleCopyInbox = () => {
    if (profile?.inbox_email) {
      navigator.clipboard.writeText(profile.inbox_email);
      setCopied(true);
      toast.success("Inbox email copied to clipboard.");
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const handleRegenerateInbox = async () => {
    if (!user) return;
    setRegenerating(true);
    try {
      const { data, error } = await supabase.rpc("generate_user_inbox_email", { p_user_id: user.id });
      if (error) throw error;
      await refreshProfile();
      toast.success(`Inbox regenerated: ${data}`);
    } catch (e: any) {
      toast.error(e.message || "Failed to regenerate inbox");
    } finally {
      setRegenerating(false);
    }
  };

  const handleToggleEmail = async (checked: boolean) => {
    if (!user) return;
    setTogglingEmail(true);
    const { error } = await supabase
      .from("profiles")
      .update({ email_enabled: checked })
      .eq("user_id", user.id);
    if (error) {
      toast.error(error.message);
    } else {
      await refreshProfile();
      toast.success(checked ? "Email enabled" : "Email disabled");
    }
    setTogglingEmail(false);
  };

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <Mail className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-base font-semibold text-foreground">Email Inbox</h3>
          <p className="text-xs text-muted-foreground">
            Forward resumes here to auto-add them to your jobs.
          </p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5 space-y-4">
        {profile?.inbox_email ? (
          <>
            <div>
              <Label className="text-xs text-muted-foreground mb-1.5 block">Your fallback inbox</Label>
              <div className="flex items-center gap-2">
                <Input
                  value={profile.inbox_email}
                  readOnly
                  className="font-mono text-sm bg-accent/50"
                />
                <Button
                  variant="outline"
                  size="icon"
                  onClick={handleCopyInbox}
                  title="Copy"
                  className="shrink-0"
                >
                  {copied ? (
                    <Check className="h-4 w-4 text-primary" />
                  ) : (
                    <Copy className="h-4 w-4" />
                  )}
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  onClick={handleRegenerateInbox}
                  title="Regenerate inbox email"
                  className="shrink-0"
                  disabled={regenerating}
                >
                  {regenerating ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <RefreshCw className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </div>
            <p className="text-xs text-muted-foreground">
              Each job also gets its own unique inbox email. Check the job detail page to copy it.
            </p>
          </>
        ) : (
          <div className="rounded-md bg-accent/50 px-3 py-3 text-sm text-muted-foreground text-center">
            No inbox email assigned yet.
          </div>
        )}
        <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
          <Label htmlFor="email-toggle" className="text-sm font-medium cursor-pointer">
            Email ingestion enabled
          </Label>
          <Switch
            id="email-toggle"
            checked={profile?.email_enabled ?? true}
            onCheckedChange={handleToggleEmail}
            disabled={togglingEmail}
          />
        </div>

        {/* How it works */}
        <Collapsible open={howItWorksOpen} onOpenChange={setHowItWorksOpen}>
          <CollapsibleTrigger asChild>
            <Button variant="ghost" size="sm" className="w-full justify-between text-muted-foreground text-xs">
              <span className="flex items-center gap-1.5">
                <Info className="h-3.5 w-3.5" />
                How email ingestion works
              </span>
              <ChevronDown className={`h-3.5 w-3.5 transition-transform ${howItWorksOpen ? "rotate-180" : ""}`} />
            </Button>
          </CollapsibleTrigger>
          <CollapsibleContent className="pt-2">
            <div className="rounded-md bg-muted/50 p-3 text-xs text-muted-foreground space-y-2.5">
              <p><strong>Per-job inbox:</strong> Each job gets a unique email address (e.g. <code className="bg-muted px-1 py-0.5 rounded text-[11px]">you+j-abc123@inbound.rankora.co</code>). Forward resumes to it and they'll be attached directly to that job.</p>
              <p><strong>Fallback inbox:</strong> Your personal inbox above routes resumes to your most recent pending job. Use this when you don't need job-specific routing.</p>
              <p><strong>Routing priority:</strong> Job-specific inbox is checked first. If no match, the fallback inbox routes to your latest pending job. If no pending job exists, one is auto-created.</p>
              <p><strong>Supported formats:</strong> PDF and DOCX attachments only. Max 20 attachments per email.</p>
            </div>
          </CollapsibleContent>
        </Collapsible>
      </CardContent>
    </Card>
  );
};

export default EmailInboxCard;

