                      </TableBody>
                    </Table>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}
      </div>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteConfirm} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteCount} resume{deleteCount > 1 ? "s" : ""}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the resume{deleteCount > 1 ? "s" : ""} and any associated results.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteConfirm} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm Edit JD Warning */}
      <AlertDialog open={confirmEditJdOpen} onOpenChange={setConfirmEditJdOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Edit Job Description?</AlertDialogTitle>
            <AlertDialogDescription className="space-y-2">
              <span className="block">
                This job has <strong>{results.length} ranked candidate{results.length !== 1 ? "s" : ""}</strong>. Editing the JD will make existing scores outdated since they were based on the original description.
              </span>
              <span className="block">
                You can re-rank resumes after editing. Standard credit charges will apply for re-ranking.
              </span>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => setEditingJd(true)}>
              Edit Anyway
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* JD Rewrite Dialog */}
      {jdRewriteOpen && (
        <JDRewriteDialog
          open={jdRewriteOpen}
          onOpenChange={setJdRewriteOpen}
          jobId={isExistingJob ? selectedJobId! : ""}
          originalJd={isExistingJob ? (selectedJob?.job_description ?? "") : jobDescription}
          onApply={async (newJd) => {
            setJobDescription(newJd);
            if (isExistingJob && selectedJobId) {
              try {
                await supabase.from("jobs").update({ job_description: newJd }).eq("id", selectedJobId);
                onJobUpdated?.(selectedJobId, { job_description: newJd });
                toast.success("Job description updated");
              } catch (err) {
                toast.error("Failed to save rewritten JD");
              }
            }
          }}
        />
      )}

      {/* Candidate Detail Sheet */}
      {(() => {
        const selectedResult = selectedCandidateId ? visibleResults.find((r) => r.id === selectedCandidateId) ?? null : null;
        return (
          <CandidateDetailSheet
            result={selectedResult}
            isOpen={!!selectedCandidateId && !!selectedResult}
            onClose={() => setSelectedCandidateId(null)}
            jobId={selectedJobId}
            jobTitle={selectedJob?.title}
            formatCandidateName={formatCandidateName}
            onDownload={downloadResume}
            onDismiss={handleDismiss}
            currentStage={selectedResult ? stageMap.get(selectedResult.resume_id)?.stage : undefined}
            stageUpdatedAt={selectedResult ? stageMap.get(selectedResult.resume_id)?.updated_at : undefined}
            onStageChange={handleStageChange}
          />
        );
      })()}
    </div>
  );
};

export default JobDetailView;

import { useState, useMemo, useRef, useEffect } from "react";
import { cn } from "@/lib/utils";
import { Plus, Clock, Briefcase, Search, MoreHorizontal, Pencil, Trash2, FileText, Home, Sparkles, Lightbulb } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import { format } from "date-fns";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { SidebarInput } from "@/components/ui/sidebar";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarSeparator,
} from "@/components/ui/sidebar";

interface PastJob {
  id: string;
  title: string | null;
  job_description: string;
  status: string;
  created_at: string;
  resume_count: number;
}

interface JobSidebarProps {
  pastJobs: PastJob[];
  selectedJobId: string | null;
  showDashboard?: boolean;
  loadingPastJobs: boolean;
  onSelectJob: (jobId: string) => void;
  onNewJob: () => void;
  onDashboard?: () => void;
  onRenameJob: (jobId: string, newTitle: string) => void;
  onDeleteJob: (jobId: string) => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
}

function getDisplayTitle(job: PastJob): string {
  if (job.title) return job.title;
  const firstLine = job.job_description.trim().split("\n")[0].trim();
  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
}

const JobSidebar = ({ pastJobs, selectedJobId, showDashboard, loadingPastJobs, onSelectJob, onNewJob, onDashboard, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
  const [search, setSearch] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState("");
  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
  const editInputRef = useRef<HTMLInputElement>(null);

  const filteredJobs = useMemo(() => {
    if (!search.trim()) return pastJobs;
    const q = search.toLowerCase();
    return pastJobs.filter(
      (job) =>
        getDisplayTitle(job).toLowerCase().includes(q) ||
        job.job_description.toLowerCase().includes(q)
    );
  }, [pastJobs, search]);

  useEffect(() => {
    if (editingId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingId]);

  const startEditing = (job: PastJob) => {
    setEditingId(job.id);
    setEditValue(getDisplayTitle(job));
  };

  const saveRename = async () => {
    if (!editingId || !editValue.trim()) {
      setEditingId(null);
      return;
    }
    try {
      const { error } = await supabase
        .from("jobs")
        .update({ title: editValue.trim() } as any)
        .eq("id", editingId);
      if (error) throw error;
      onRenameJob(editingId, editValue.trim());
      toast.success("Job renamed");
    } catch {
      toast.error("Failed to rename job");
    }
    setEditingId(null);
  };

  const cancelEditing = () => setEditingId(null);

  const confirmDelete = () => {
    if (deleteJobId) {
      onDeleteJob(deleteJobId);
      setDeleteJobId(null);
    }
  };

  return (
    <>
      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
        <SidebarHeader className="p-3">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
            <SidebarInput
              placeholder="Search…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8"
            />
          </div>
        </SidebarHeader>

        <SidebarContent>
          {/* HOME section */}
          <SidebarGroup>
            <SidebarGroupLabel>Home</SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {isAuthenticated && onDashboard && (
                  <SidebarMenuItem>
                    <SidebarMenuButton isActive={showDashboard && !selectedJobId} onClick={onDashboard}>
                      <Home className="h-4 w-4" />
                      <span>Dashboard</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                )}
                <SidebarMenuItem>
                  <SidebarMenuButton
                    isActive={!selectedJobId && !showDashboard}
                    onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }}
                  >
                    <Plus className="h-4 w-4" />
                    <span>New Job</span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          <SidebarSeparator />

          {/* JOBS section */}
          <SidebarGroup className="flex-1">
            <SidebarGroupLabel className="flex items-center gap-2">
              <span>Jobs</span>
              {search && <span className="ml-auto text-[11px]">({filteredJobs.length})</span>}
            </SidebarGroupLabel>
            <SidebarGroupContent>
              {!isAuthenticated ? (
                <div className="px-3 py-3">
                  <button
                    onClick={() => onAuthRequired?.()}
                    className="w-full rounded-lg border border-dashed border-border px-3 py-5 text-center hover:border-primary/50 hover:bg-primary/5 transition-all group"
                  >
                    <Briefcase className="h-5 w-5 text-muted-foreground group-hover:text-primary mx-auto mb-2 transition-colors" />
                    <p className="text-xs font-medium text-foreground mb-1">No jobs yet</p>
                    <p className="text-[11px] text-muted-foreground mb-3">Sign in to view your job history and ranked results</p>
                    <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary">
                      Sign in to get started →
                    </span>
                  </button>
                </div>
              ) : loadingPastJobs ? (
                <div className="space-y-1.5 px-2">
                  {[0, 1, 2].map((i) => (
                    <div key={i} className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2" style={{ animationDelay: `${i * 80}ms`, animationFillMode: "backwards" }}>
                      <Skeleton className="h-4 w-3/4 bg-sidebar-accent" />
                      <div className="flex items-center justify-between">
                        <Skeleton className="h-3 w-20 bg-sidebar-accent" />
                        <Skeleton className="h-3 w-24 bg-sidebar-accent" />
                      </div>
                    </div>
                  ))}
                </div>
              ) : filteredJobs.length === 0 ? (
                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
                  {search ? "No matching jobs found." : "No jobs yet. Create your first one!"}
                </p>
              ) : (
                <SidebarMenu className="space-y-1.5 px-2">
                  {filteredJobs.map((job, i) => (
                    <SidebarMenuItem key={job.id} className="animate-in fade-in slide-in-from-left-2 duration-200" style={{ animationDelay: `${i * 40}ms`, animationFillMode: "backwards" }}>
                      {editingId === job.id ? (
                        <div className="mx-0 rounded-lg border border-primary/50 bg-card shadow-sm px-3 py-2">
                          <Input
                            ref={editInputRef}
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === "Enter") saveRename();
                              if (e.key === "Escape") cancelEditing();
                            }}
                            onBlur={saveRename}
                            className="h-7 text-sm"
                          />
                        </div>
                      ) : (
                        <SidebarMenuButton
                          isActive={selectedJobId === job.id}
                          onClick={() => onSelectJob(job.id)}
                          className={cn(
                            "flex flex-col items-start gap-1 h-auto py-2.5 px-3 group/item",
                            "rounded-lg border transition-colors",
                            selectedJobId === job.id
                              ? "border-l-2 border-l-primary bg-sidebar-accent"
                              : "border-transparent hover:bg-sidebar-accent/50"
                          )}
                        >
                          <div className="flex items-center gap-1 w-full">
                            <span className="text-sm leading-snug line-clamp-2 flex-1">
                              {getDisplayTitle(job)}
                            </span>
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-0.5 rounded hover:bg-accent shrink-0">
                                  <MoreHorizontal className="h-3.5 w-3.5 text-muted-foreground" />
                                </button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end" className="w-36">
                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
                                  <Pencil className="h-3.5 w-3.5 mr-2" />
                                  Rename
                                </DropdownMenuItem>
                                <DropdownMenuItem
                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
                                  className="text-destructive focus:text-destructive"
                                >
                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
                                  Delete
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </div>
                          <div className="flex items-center gap-2 w-full">
                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5">
                              <FileText className="h-2.5 w-2.5" />
                              {job.resume_count} {job.resume_count === 1 ? "resume" : "resumes"}
                            </span>
                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5 ml-auto">
                              <Clock className="h-2.5 w-2.5" />
                              {format(new Date(job.created_at), "MMM d, yyyy")}
                            </span>
                          </div>
                        </SidebarMenuButton>
                      )}
                    </SidebarMenuItem>
                  ))}
                </SidebarMenu>
              )}
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>

        <SidebarFooter className="p-3 space-y-2">
          <SidebarSeparator />
          <div className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2.5">
            <div className="flex items-center gap-2">
              <Sparkles className="h-3.5 w-3.5 text-sidebar-primary" />
              <span className="text-xs font-semibold text-sidebar-foreground">What's new</span>
            </div>
            <div className="flex gap-2">
              <a
                href="/request-feature"
                className="flex-1 text-center text-xs font-medium py-1.5 rounded-md border border-sidebar-border bg-sidebar-accent text-sidebar-foreground hover:bg-sidebar-accent/80 transition-colors"
              >
                Request Feature
              </a>
              <a
                href="/changelog"
                className="flex-1 text-center text-xs font-medium py-1.5 rounded-md border border-sidebar-border bg-sidebar-accent text-sidebar-foreground hover:bg-sidebar-accent/80 transition-colors"
              >
                Changelog
              </a>
            </div>
          </div>
        </SidebarFooter>
      </Sidebar>

      <AlertDialog open={!!deleteJobId} onOpenChange={(open) => !open && setDeleteJobId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this job?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete this job and all its resumes. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

export default JobSidebar;

