                          </div>
                          <div className="flex items-center gap-2 w-full">
                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5">
                              <FileText className="h-2.5 w-2.5" />
                              {job.resume_count} {job.resume_count === 1 ? "resume" : "resumes"}
                            </span>
                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5 ml-auto">
                              <Clock className="h-2.5 w-2.5" />
                              {format(new Date(job.created_at), "MMM d, yyyy")}
                            </span>
                          </div>
                        </SidebarMenuButton>
                      )}
                    </SidebarMenuItem>
                  ))}
                </SidebarMenu>
              )}
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>

        <SidebarFooter className="p-3 space-y-2">
          <SidebarSeparator />
          <div className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2.5">
            <div className="flex items-center gap-2">
              <Sparkles className="h-3.5 w-3.5 text-sidebar-primary" />
              <span className="text-xs font-semibold text-sidebar-foreground">What's new</span>
