          {stuckJobDetected && (
            <div className="rounded-lg border border-amber-500/40 bg-amber-500/5 p-4 flex items-start gap-3 animate-fade-in">
              <AlertTriangle className="h-5 w-5 mt-0.5 shrink-0 text-amber-500" />
              <div className="flex-1">
                <p className="text-sm font-medium">Ranking appears stuck</p>
                <p className="text-sm text-muted-foreground mt-0.5">
                  Processing has been running for over 5 minutes. Some resumes may not have been scored.
                </p>
                <Button
                  size="sm"
                  variant="outline"
                  className="mt-2"
                  onClick={handleRetryStuck}
                  disabled={retrying}
                >
                  {retrying ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <RefreshCw className="h-3 w-3 mr-1" />}
                  Retry unscored resumes
                </Button>
              </div>
            </div>
          )}
          {ranking && (
            <div className="space-y-2 animate-fade-in">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-sm text-primary font-medium">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  {rankingProgress < 25 ? "Analyzing job…" : rankingProgress < 40 ? "Preparing resumes…" : rankingProgress < 60 ? "Parsing resumes…" : totalToScore > 0 ? `Scoring ${scoredCount}/${totalToScore}…` : "Scoring candidates…"}
                </div>
              </div>
              <Progress value={rankingProgress} className="h-2" aria-label={`Ranking progress: ${Math.round(rankingProgress)}%`} />
            </div>
          )}
        </div>


        {/* Results Table */}
        {visibleResults.length > 0 && (
          <div ref={resultsRef}>
            <Card>
              <CardHeader className="px-4 py-3 space-y-3">
                {/* Row 1: Title + stage filters */}
                <div className="flex items-center gap-2 flex-wrap">
                  <CardTitle className="text-sm font-semibold">
                    Results ({visibleResults.filter(r => !r.pending).length}{visibleResults.some(r => r.pending) ? ` scored · ${visibleResults.filter(r => r.pending).length} pending` : ""})
                  </CardTitle>
                  {nonArchivedResults.some(r => !r.pending) && (
                    <div className="flex items-center gap-1">
                      {(["applied", "screened", "interview", "offer", "hired", "rejected"] as const).map((stage) => {
                        const count = effectiveStageCounts[stage];
                        if (count === 0) return null;
                        const isActive = stageFilter === stage;
                        const colors: Record<string, string> = {
                          applied: isActive ? "bg-muted-foreground text-background" : "bg-muted text-muted-foreground hover:bg-muted-foreground/20",
                          screened: isActive ? "bg-blue-600 text-white dark:bg-blue-500" : "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 hover:bg-blue-200 dark:hover:bg-blue-900/50",
                          interview: isActive ? "bg-purple-600 text-white dark:bg-purple-500" : "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400 hover:bg-purple-200 dark:hover:bg-purple-900/50",
                          offer: isActive ? "bg-amber-600 text-white dark:bg-amber-500" : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 hover:bg-amber-200 dark:hover:bg-amber-900/50",
                          hired: isActive ? "bg-emerald-600 text-white dark:bg-emerald-500" : "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 hover:bg-emerald-200 dark:hover:bg-emerald-900/50",
                          rejected: isActive ? "bg-red-600 text-white dark:bg-red-500" : "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 hover:bg-red-200 dark:hover:bg-red-900/50",
                        };
                        return (
                          <button
                            key={stage}
                            onClick={() => setStageFilter(isActive ? null : stage)}
                            className={`text-[11px] font-medium px-1.5 py-0.5 rounded transition-colors ${colors[stage]}`}
                          >
                            {count} {stage.charAt(0).toUpperCase() + stage.slice(1)}
                            {isActive && " ×"}
                          </button>
                        );
                      })}
                    </div>
                  )}
                  <div className="flex items-center gap-1.5 ml-auto">
                    {dismissedResumes.size > 0 && (
                      <Button
                        variant={showArchived ? "secondary" : "outline"}
                        size="sm"
                        className="h-7 gap-1.5 text-xs"
                        onClick={() => setShowArchived((v) => !v)}
                      >
                        <FolderOpen className="h-3 w-3" />
                        Archived ({dismissedResumes.size})
                      </Button>
                    )}
                    {visibleResults.length > 0 && (
                      <Button
                        variant="outline"
                        size="sm"
                        className="h-7 gap-1.5 text-xs"
                        onClick={() => {
                          const formatCandidateNameLocal = (filename: string) => {
                            const name = filename.replace(/\.\w+$/, "");
                            if (UUID_REGEX.test(name)) return "Candidate";
                            return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
                          };
                          const rows = visibleResults.filter((r) => !r.pending).map((r, i) => {
                            const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.length : 0;
                            const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.length : 0;
                            const total = matched + missing;
                            const jdAlignment = total > 0 ? Math.round((matched / total) * 100) : 0;
                            const stage = stageMap.get(r.resume_id)?.stage ?? "applied";
                            return {
                              "Rank": i + 1,
                              "Candidate Name": r.candidate_name || formatCandidateNameLocal(r.filename),
                              "Email": r.candidate_email ?? "",
                              "Phone": r.candidate_phone ?? "",
                              "Location": r.candidate_location ?? "",
                              "Stage": stage.charAt(0).toUpperCase() + stage.slice(1),
                              "Overall Score": r.overall_score?.toFixed(0) ?? "0",
                              "Confidence": (r.confidence ?? 0).toFixed(0),
                              "Hard Fit": r.hard_fit ? "Yes" : "No",
                              "JD Alignment %": jdAlignment,
                              "Strengths": (r.strengths_json ?? []).join("; "),
                              "Gaps": (r.gaps_json ?? []).join("; "),
                              "Missing Skills": (r.missing_skills ?? []).join("; "),
                            };
                          });
                          exportToCSV(rows, selectedJob?.title || "results");
                        }}
                      >
                        <FileSpreadsheet className="h-3 w-3" />
                        Export
                      </Button>
                    )}
                    {isExistingJob && existingResumes.length > 0 && (
                      <Button variant="outline" size="sm" className="h-7 gap-1.5 text-xs" disabled={ranking} onClick={handleRerank}>
                        {ranking ? <Loader2 className="h-3 w-3 animate-spin" /> : <RefreshCw className="h-3 w-3" />}
                        Re-rank
                      </Button>
                    )}
                  </div>
                </div>

                {/* Row 2: Selection actions — only when candidates are selected */}
                {selectedResumes.size > 0 && (
                  <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 border border-border">
                    <span className="text-xs font-medium text-foreground">{selectedResumes.size} selected</span>
                    <div className="flex items-center gap-1.5 ml-auto">
                      <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => setSelectedResumes(new Set())}>
                        Clear
                      </Button>
                      <Button variant="destructive" size="sm" className="h-7 gap-1.5 text-xs" onClick={() => setDeleteConfirm({ type: "bulk" })}>
                        <Trash2 className="h-3 w-3" /> Delete
                      </Button>
                    </div>
                  </div>
                )}
              </CardHeader>
              <CardContent className="p-0">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader className="sticky top-0 bg-card z-10">
                      <TableRow>
                        <TableHead className="w-10">
                          <Checkbox
                            aria-label="Select all candidates"
                            checked={visibleResults.length > 0 && visibleResults.every(r => selectedResumes.has(r.resume_id))}
                            onCheckedChange={(checked) => {
                              if (checked) setSelectedResumes(prev => new Set([...prev, ...visibleResults.map(r => r.resume_id)]));
                              else setSelectedResumes(prev => { const next = new Set(prev); visibleResults.forEach(r => next.delete(r.resume_id)); return next; });
                            }}
                          />
                        </TableHead>
                        <TableHead className="w-14 text-center">#</TableHead>
                        <TableHead>Candidate</TableHead>
                        <TableHead className="w-32">Match</TableHead>
                        <TableHead className="w-20">Strength</TableHead>
                        <TableHead className="w-36"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {ranking && visibleResults.filter(r => !r.pending).length === 0 && (
                        <>
                          {[0, 1, 2, 3, 4].map((i) => (
                            <TableRow key={`skel-${i}`} className="animate-pulse">
                              <TableCell><Skeleton className="h-4 w-4 rounded" /></TableCell>
                              <TableCell className="text-center"><Skeleton className="h-4 w-6 mx-auto rounded" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-40" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                              <TableCell><Skeleton className="h-5 w-16 rounded-full" /></TableCell>
                              <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                            </TableRow>
                          ))}
                        </>
                      )}
                      {visibleResults.map((r, index) => (
                        <CandidateRow
                          key={r.id}
                          result={r}
                          index={index}
                          isSelected={selectedResumes.has(r.resume_id)}
                          isActive={selectedCandidateId === r.id}
                          jobId={selectedJobId}
                          jobTitle={selectedJob?.title}
                          onSelect={selectCandidate}
                          onToggleSelect={toggleSelectResume}
                          onDownload={downloadResume}
                          onDismiss={handleDismiss}
                          formatCandidateName={formatCandidateName}
                          currentStage={stageMap.get(r.resume_id)?.stage}
                          isDuplicate={duplicateResumeIds.has(r.resume_id)}
                        />
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </CardContent>
            </Card>

            {/* Archived Candidates Panel */}
            {showArchived && archivedResults.length > 0 && (
              <Card className="mt-3 border-amber-200 dark:border-amber-800">
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-base flex items-center gap-2 text-amber-700 dark:text-amber-400">
                      <Archive className="h-4 w-4" />
                      Archived Candidates ({archivedResults.length})
                    </CardTitle>
                    <button
                      onClick={() => setShowArchived(false)}
                      className="text-muted-foreground hover:text-foreground"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="overflow-x-auto">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead className="w-14 text-center pl-4">#</TableHead>
                          <TableHead>Candidate</TableHead>
                          <TableHead className="w-32">Match</TableHead>
                          <TableHead className="w-20">Strength</TableHead>
                          <TableHead className="w-20 text-right pr-4">Restore</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {archivedResults.map((r, index) => {
                          const scoreColor = r.overall_score >= 70 ? "text-score-skills" : r.overall_score >= 40 ? "text-warning" : "text-destructive";
                          const strengthLabel = r.overall_score >= 70 ? "Strong" : r.overall_score >= 40 ? "Good" : "Weak";
                          const strengthVariant = r.overall_score >= 70 ? "success" : r.overall_score >= 40 ? "warning" : "destructive";
                          return (
                            <TableRow key={r.id} className="opacity-60 hover:opacity-100 transition-opacity">
                              <TableCell className="text-center text-sm text-muted-foreground pl-4">{index + 1}</TableCell>
                              <TableCell className="font-medium text-sm">
                                {r.candidate_name || formatCandidateName(r.filename)}
                              </TableCell>
                              <TableCell>
                                {!r.pending && (
                                  <div className="flex items-center gap-2">
                                    <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[80px]">
                                      <div
                                        className={`h-full rounded-full transition-all ${r.overall_score >= 70 ? "bg-score-skills" : r.overall_score >= 40 ? "bg-warning" : "bg-destructive"}`}
                                        style={{ width: `${Math.min(r.overall_score, 100)}%` }}
                                      />
                                    </div>
                                    <span className={`text-sm font-semibold tabular-nums ${scoreColor}`}>{r.overall_score?.toFixed(0)}%</span>
                                  </div>
                                )}
                              </TableCell>
                              <TableCell>
                                {!r.pending && <Badge variant={strengthVariant as "success" | "warning" | "destructive"} className="text-[11px]">{strengthLabel}</Badge>}
                              </TableCell>
                              <TableCell className="text-right pr-4">
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="h-7 w-7 text-muted-foreground hover:text-amber-600"
                                  onClick={() => handleUnarchive(r.resume_id)}
                                  title="Restore candidate"
                                >
                                  <ArchiveRestore className="h-3.5 w-3.5" />
                                </Button>
                              </TableCell>
                            </TableRow>
                          );
                        })}
                      </TableBody>
                    </Table>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}
      </div>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteConfirm} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteCount} resume{deleteCount > 1 ? "s" : ""}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the resume{deleteCount > 1 ? "s" : ""} and any associated results.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteConfirm} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm Edit JD Warning */}
      <AlertDialog open={confirmEditJdOpen} onOpenChange={setConfirmEditJdOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Edit Job Description?</AlertDialogTitle>
            <AlertDialogDescription className="space-y-2">
              <span className="block">
                This job has <strong>{results.length} ranked candidate{results.length !== 1 ? "s" : ""}</strong>. Editing the JD will make existing scores outdated since they were based on the original description.
              </span>
              <span className="block">
                You can re-rank resumes after editing. Standard credit charges will apply for re-ranking.
              </span>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => setEditingJd(true)}>
              Edit Anyway
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* JD Rewrite Dialog */}
      {jdRewriteOpen && (
        <JDRewriteDialog
          open={jdRewriteOpen}
          onOpenChange={setJdRewriteOpen}
          jobId={isExistingJob ? selectedJobId! : ""}
          originalJd={isExistingJob ? (selectedJob?.job_description ?? "") : jobDescription}
          onApply={async (newJd) => {
            setJobDescription(newJd);
            if (isExistingJob && selectedJobId) {
              try {
                await supabase.from("jobs").update({ job_description: newJd }).eq("id", selectedJobId);
                onJobUpdated?.(selectedJobId, { job_description: newJd });
                toast.success("Job description updated");
              } catch (err) {
                toast.error("Failed to save rewritten JD");
              }
            }
          }}
        />
      )}

      {/* Candidate Detail Sheet */}
      {(() => {
        const selectedResult = selectedCandidateId ? visibleResults.find((r) => r.id === selectedCandidateId) ?? null : null;
        return (
          <CandidateDetailSheet
            result={selectedResult}
            isOpen={!!selectedCandidateId && !!selectedResult}
            onClose={() => setSelectedCandidateId(null)}
            jobId={selectedJobId}
            jobTitle={selectedJob?.title}
            formatCandidateName={formatCandidateName}
            onDownload={downloadResume}
            onDismiss={handleDismiss}
            currentStage={selectedResult ? stageMap.get(selectedResult.resume_id)?.stage : undefined}
            stageUpdatedAt={selectedResult ? stageMap.get(selectedResult.resume_id)?.updated_at : undefined}
            onStageChange={handleStageChange}
          />
        );
      })()}
    </div>
  );
};

export default JobDetailView;

import { useState, useMemo, useRef, useEffect } from "react";
import { cn } from "@/lib/utils";
import { Plus, Clock, Briefcase, Search, MoreHorizontal, Pencil, Trash2, FileText, Home, Sparkles, Lightbulb } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import { format } from "date-fns";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { SidebarInput } from "@/components/ui/sidebar";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarSeparator,
} from "@/components/ui/sidebar";

interface PastJob {
  id: string;
  title: string | null;
  job_description: string;
  status: string;
  created_at: string;
  resume_count: number;
}

interface JobSidebarProps {
  pastJobs: PastJob[];
  selectedJobId: string | null;
  showDashboard?: boolean;
  loadingPastJobs: boolean;
  onSelectJob: (jobId: string) => void;
  onNewJob: () => void;
  onDashboard?: () => void;
  onRenameJob: (jobId: string, newTitle: string) => void;
  onDeleteJob: (jobId: string) => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
}

function getDisplayTitle(job: PastJob): string {
  if (job.title) return job.title;
  const firstLine = job.job_description.trim().split("\n")[0].trim();
  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
}

const JobSidebar = ({ pastJobs, selectedJobId, showDashboard, loadingPastJobs, onSelectJob, onNewJob, onDashboard, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
  const [search, setSearch] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState("");
  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
  const editInputRef = useRef<HTMLInputElement>(null);

  const filteredJobs = useMemo(() => {
    if (!search.trim()) return pastJobs;
    const q = search.toLowerCase();
    return pastJobs.filter(
      (job) =>
        getDisplayTitle(job).toLowerCase().includes(q) ||
        job.job_description.toLowerCase().includes(q)
    );
  }, [pastJobs, search]);

  useEffect(() => {
    if (editingId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingId]);

  const startEditing = (job: PastJob) => {
    setEditingId(job.id);
    setEditValue(getDisplayTitle(job));
  };

  const saveRename = async () => {
    if (!editingId || !editValue.trim()) {
      setEditingId(null);
      return;
    }
    try {
      const { error } = await supabase
        .from("jobs")
        .update({ title: editValue.trim() } as any)
        .eq("id", editingId);
      if (error) throw error;
      onRenameJob(editingId, editValue.trim());
      toast.success("Job renamed");
    } catch {
      toast.error("Failed to rename job");
    }
    setEditingId(null);
  };

  const cancelEditing = () => setEditingId(null);

  const confirmDelete = () => {
    if (deleteJobId) {
      onDeleteJob(deleteJobId);
      setDeleteJobId(null);
    }
  };

  return (
    <>
      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
        <SidebarHeader className="p-3">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
            <SidebarInput
              placeholder="Search…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8"
            />
          </div>
        </SidebarHeader>

        <SidebarContent>
          {/* HOME section */}
          <SidebarGroup>
            <SidebarGroupLabel>Home</SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {isAuthenticated && onDashboard && (
                  <SidebarMenuItem>
                    <SidebarMenuButton isActive={showDashboard && !selectedJobId} onClick={onDashboard}>
                      <Home className="h-4 w-4" />
                      <span>Dashboard</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                )}
                <SidebarMenuItem>
                  <SidebarMenuButton
                    isActive={!selectedJobId && !showDashboard}
                    onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }}
                  >
                    <Plus className="h-4 w-4" />
                    <span>New Job</span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          <SidebarSeparator />

          {/* JOBS section */}
          <SidebarGroup className="flex-1">
            <SidebarGroupLabel className="flex items-center gap-2">
              <span>Jobs</span>
              {search && <span className="ml-auto text-[11px]">({filteredJobs.length})</span>}
            </SidebarGroupLabel>
            <SidebarGroupContent>
              {!isAuthenticated ? (
                <div className="px-3 py-3">
                  <button
                    onClick={() => onAuthRequired?.()}
                    className="w-full rounded-lg border border-dashed border-border px-3 py-5 text-center hover:border-primary/50 hover:bg-primary/5 transition-all group"
                  >
                    <Briefcase className="h-5 w-5 text-muted-foreground group-hover:text-primary mx-auto mb-2 transition-colors" />
                    <p className="text-xs font-medium text-foreground mb-1">No jobs yet</p>
                    <p className="text-[11px] text-muted-foreground mb-3">Sign in to view your job history and ranked results</p>
                    <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary">
                      Sign in to get started →
                    </span>
                  </button>
                </div>
              ) : loadingPastJobs ? (
                <div className="space-y-1.5 px-2">
                  {[0, 1, 2].map((i) => (
                    <div key={i} className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2" style={{ animationDelay: `${i * 80}ms`, animationFillMode: "backwards" }}>
                      <Skeleton className="h-4 w-3/4 bg-sidebar-accent" />
                      <div className="flex items-center justify-between">
                        <Skeleton className="h-3 w-20 bg-sidebar-accent" />
                        <Skeleton className="h-3 w-24 bg-sidebar-accent" />
                      </div>
                    </div>
                  ))}
                </div>
              ) : filteredJobs.length === 0 ? (
                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
                  {search ? "No matching jobs found." : "No jobs yet. Create your first one!"}
                </p>
              ) : (
                <SidebarMenu className="space-y-1.5 px-2">
                  {filteredJobs.map((job, i) => (
                    <SidebarMenuItem key={job.id} className="animate-in fade-in slide-in-from-left-2 duration-200" style={{ animationDelay: `${i * 40}ms`, animationFillMode: "backwards" }}>
                      {editingId === job.id ? (
                        <div className="mx-0 rounded-lg border border-primary/50 bg-card shadow-sm px-3 py-2">
                          <Input
                            ref={editInputRef}
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === "Enter") saveRename();
                              if (e.key === "Escape") cancelEditing();
                            }}
                            onBlur={saveRename}
                            className="h-7 text-sm"
                          />
                        </div>
                      ) : (
                        <SidebarMenuButton
                          isActive={selectedJobId === job.id}
                          onClick={() => onSelectJob(job.id)}
                          className={cn(
                            "flex flex-col items-start gap-1 h-auto py-2.5 px-3 group/item",
                            "rounded-lg border transition-colors",
                            selectedJobId === job.id
                              ? "border-l-2 border-l-primary bg-sidebar-accent"
                              : "border-transparent hover:bg-sidebar-accent/50"
                          )}
                        >
                          <div className="flex items-center gap-1 w-full">
                            <span className="text-sm leading-snug line-clamp-2 flex-1" title={getDisplayTitle(job)}>
                              {getDisplayTitle(job)}
                            </span>
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-1.5 rounded hover:bg-accent shrink-0" aria-label="Job actions">
                                  <MoreHorizontal className="h-4 w-4 text-muted-foreground" />
                                </button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end" className="w-36">
                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
                                  <Pencil className="h-3.5 w-3.5 mr-2" />
                                  Rename
                                </DropdownMenuItem>
                                <DropdownMenuItem
                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
                                  className="text-destructive focus:text-destructive"
                                >
                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
                                  Delete
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </div>
                          <div className="flex items-center gap-2 w-full">
                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5">
                              <FileText className="h-2.5 w-2.5" />
                              {job.resume_count} {job.resume_count === 1 ? "resume" : "resumes"}
                            </span>
                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5 ml-auto">
                              <Clock className="h-2.5 w-2.5" />
                              {format(new Date(job.created_at), "MMM d, yyyy")}
                            </span>
                          </div>
                        </SidebarMenuButton>
                      )}
                    </SidebarMenuItem>
                  ))}
                </SidebarMenu>
              )}
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>

        <SidebarFooter className="p-3 space-y-2">
          <SidebarSeparator />
          <div className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2.5">
            <div className="flex items-center gap-2">
              <Sparkles className="h-3.5 w-3.5 text-sidebar-primary" />
              <span className="text-xs font-semibold text-sidebar-foreground">What's new</span>
            </div>
            <div className="flex gap-2">
              <a
                href="/request-feature"
                className="flex-1 text-center text-xs font-medium py-1.5 rounded-md border border-sidebar-border bg-sidebar-accent text-sidebar-foreground hover:bg-sidebar-accent/80 transition-colors"
              >
                Request Feature
              </a>
              <a
                href="/changelog"
                className="flex-1 text-center text-xs font-medium py-1.5 rounded-md border border-sidebar-border bg-sidebar-accent text-sidebar-foreground hover:bg-sidebar-accent/80 transition-colors"
              >
                Changelog
              </a>
            </div>
          </div>
        </SidebarFooter>
      </Sidebar>

      <AlertDialog open={!!deleteJobId} onOpenChange={(open) => !open && setDeleteJobId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this job?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete this job and all its resumes. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

export default JobSidebar;

