                                {r.candidate_name || formatCandidateName(r.filename)}
                              </TableCell>
                              <TableCell>
                                {!r.pending && (
                                  <div className="flex items-center gap-2">
                                    <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[80px]">
                                      <div
                                        className={`h-full rounded-full transition-all ${r.overall_score >= 70 ? "bg-score-skills" : r.overall_score >= 40 ? "bg-warning" : "bg-destructive"}`}
