        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteCount} resume{deleteCount > 1 ? "s" : ""}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete {deleteCount} resume{deleteCount > 1 ? "s" : ""} and any associated results. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteConfirm} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Confirm Edit JD Warning */}
      <AlertDialog open={confirmEditJdOpen} onOpenChange={setConfirmEditJdOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Edit Job Description?</AlertDialogTitle>
            <AlertDialogDescription className="space-y-2">
              <span className="block">
                This job has <strong>{results.length} ranked candidate{results.length !== 1 ? "s" : ""}</strong>. Editing the JD will make existing scores outdated since they were based on the original description.
              </span>
              <span className="block">
                You can re-rank resumes after editing. Standard credit charges will apply for re-ranking.
              </span>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => setEditingJd(true)}>
              Edit Anyway
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* JD Rewrite Dialog */}
      {jdRewriteOpen && (
        <JDRewriteDialog
          open={jdRewriteOpen}
          onOpenChange={setJdRewriteOpen}
          jobId={isExistingJob ? selectedJobId! : ""}
          originalJd={isExistingJob ? (selectedJob?.job_description ?? "") : jobDescription}
          onApply={async (newJd) => {
            setJobDescription(newJd);
            if (isExistingJob && selectedJobId) {
              try {
                await supabase.from("jobs").update({ job_description: newJd }).eq("id", selectedJobId);
                onJobUpdated?.(selectedJobId, { job_description: newJd });
                toast.success("Job description updated");
              } catch (err) {
                toast.error("Failed to save rewritten JD");
              }
            }
          }}
        />
      )}

      {/* Candidate Detail Sheet */}
      {(() => {
        const selectedResult = selectedCandidateId ? visibleResults.find((r) => r.id === selectedCandidateId) ?? null : null;
        return (
          <CandidateDetailSheet
            result={selectedResult}
            isOpen={!!selectedCandidateId && !!selectedResult}
            onClose={() => setSelectedCandidateId(null)}
            jobId={selectedJobId}
            jobTitle={selectedJob?.title}
            formatCandidateName={formatCandidateName}
            onDownload={downloadResume}
            onDismiss={handleDismiss}
            currentStage={selectedResult ? stageMap.get(selectedResult.resume_id)?.stage : undefined}
            stageUpdatedAt={selectedResult ? stageMap.get(selectedResult.resume_id)?.updated_at : undefined}
            onStageChange={handleStageChange}
          />
        );
      })()}
    </div>
  );
};

export default JobDetailView;

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Shield, Eye, EyeOff } from "lucide-react";

const ChangePasswordCard = () => {
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [saving, setSaving] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
      toast.error("Password too short — must be at least 6 characters.");
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error("Passwords don't match");
      return;
    }
    setSaving(true);
    const { error } = await supabase.auth.updateUser({ password: newPassword });
    if (error) {
      toast.error(error.message);
    } else {
      toast.success("Password updated");
      setNewPassword("");
      setConfirmPassword("");
    }
    setSaving(false);
  };

  const passwordsMatch = newPassword && confirmPassword && newPassword === confirmPassword;
  const passwordsMismatch = confirmPassword && newPassword !== confirmPassword;

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <Shield className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-base font-semibold text-foreground">Change Password</h3>
          <p className="text-xs text-muted-foreground">Update your account password.</p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5 space-y-4">
        <div className="space-y-2">
          <Label htmlFor="new-password" className="text-sm">New password</Label>
          <div className="relative">
            <Input
              id="new-password"
              type={showPassword ? "text" : "password"}
              placeholder="Min 6 characters"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="pr-10"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
              aria-label={showPassword ? "Hide password" : "Show password"}
            >
              {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
            </button>
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="confirm-password" className="text-sm">Confirm password</Label>
          <Input
            id="confirm-password"
            type={showPassword ? "text" : "password"}
            placeholder="Re-enter password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            className={passwordsMismatch ? "border-destructive focus-visible:ring-destructive" : passwordsMatch ? "border-primary/50 focus-visible:ring-primary" : ""}
          />
          {passwordsMismatch && (
            <p className="text-xs text-destructive">Passwords don't match.</p>
          )}
          {passwordsMatch && (
            <p className="text-xs text-primary">Passwords match ✓</p>
          )}
        </div>
        <Button
          onClick={handleChangePassword}
          disabled={saving || !newPassword || !passwordsMatch}
          className="w-full"
        >
          {saving ? "Updating…" : "Update password"}
        </Button>
      </CardContent>
    </Card>
  );
};

export default ChangePasswordCard;

