                          <div className="flex items-center gap-1 w-full">
                            <span className="text-sm leading-snug line-clamp-2 flex-1" title={getDisplayTitle(job)}>
                              {getDisplayTitle(job)}
                            </span>
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-1.5 rounded hover:bg-accent shrink-0" aria-label="Job actions">
                                  <MoreHorizontal className="h-4 w-4 text-muted-foreground" />
                                </button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end" className="w-36">
                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
                                  <Pencil className="h-3.5 w-3.5 mr-2" />
                                  Rename
                                </DropdownMenuItem>
                                <DropdownMenuItem
                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
                                  className="text-destructive focus:text-destructive"
                                >
                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
                                  Delete
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </div>
                          <div className="flex items-center gap-2 w-full">
                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5">
