              <Sparkles className="h-3.5 w-3.5 text-sidebar-primary" />
              <span className="text-xs font-semibold text-sidebar-foreground">What's new</span>
            </div>
            <div className="flex gap-2">
              <a
                href="/request-feature"
                className="flex-1 text-center text-xs font-medium py-1.5 rounded-md border border-sidebar-border bg-sidebar-accent text-sidebar-foreground hover:bg-sidebar-accent/80 transition-colors"
              >
                Request Feature
              </a>
              <a
                href="/changelog"
                className="flex-1 text-center text-xs font-medium py-1.5 rounded-md border border-sidebar-border bg-sidebar-accent text-sidebar-foreground hover:bg-sidebar-accent/80 transition-colors"
              >
                Changelog
              </a>
            </div>
          </div>
        </SidebarFooter>
      </Sidebar>

      <AlertDialog open={!!deleteJobId} onOpenChange={(open) => !open && setDeleteJobId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this job?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete "{pastJobs.find(j => j.id === deleteJobId)?.title || "Untitled Job"}" and all its resumes. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

export default JobSidebar;

