import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Coins, Loader2, ShoppingCart, Sparkles, Crown, Wallet } from "lucide-react";
import SubscriptionDialog from "@/components/SubscriptionDialog";

interface BuyCreditsDialogProps {
  trigger?: React.ReactNode;
}

const QUICK_AMOUNTS = [5, 10, 25, 50];

const BuyCreditsDialog = ({ trigger }: BuyCreditsDialogProps) => {
  const { user } = useAuth();
  const [open, setOpen] = useState(false);
  const [amount, setAmount] = useState("");
  const [buying, setBuying] = useState(false);

  const { data: config } = useQuery({
    queryKey: ["platform_config_topup"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("payg_per_resume_cost, topup_min_amount")
        .limit(1)
        .single();
      if (error) throw error;
      return data as any;
    },
  });

  const perResumeCost = config?.payg_per_resume_cost ?? 0.07;
  const minAmount = config?.topup_min_amount ?? 1;
  const numericAmount = parseFloat(amount) || 0;
  const calculatedCredits = perResumeCost > 0 ? Math.floor(numericAmount / perResumeCost) : 0;
  const isValid = numericAmount >= minAmount;

  const handleBuy = async () => {
    if (!user || !isValid) return;
    setBuying(true);

    try {
      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
        body: {
          topup_amount: numericAmount,
          return_url: `${window.location.origin}/payment/callback`,
        },
      });

      if (error) throw error;

      if (!data?.checkout_url) {
        toast.error(data?.error || "Failed to create checkout session");
        return;
      }

      window.location.href = data.checkout_url;
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setBuying(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {trigger || (
          <Button variant="outline" className="gap-2">
            <ShoppingCart className="h-4 w-4" />
            Buy Credits
          </Button>
        )}
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-primary" />
            Add Credits
          </DialogTitle>
          <DialogDescription>
            Enter any amount to recharge your wallet. Credits never expire.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 pt-2">
          {/* Quick amount buttons */}
          <div className="flex gap-2 flex-wrap">
            {QUICK_AMOUNTS.filter(a => a >= minAmount).map((a) => (
              <Button
                key={a}
                variant={numericAmount === a ? "default" : "outline"}
                size="sm"
                className="flex-1 min-w-[60px]"
                onClick={() => setAmount(String(a))}
              >
                ${a}
              </Button>
            ))}
          </div>

          {/* Amount input */}
          <div>
            <label className="text-sm font-medium text-foreground mb-1.5 block">
              Custom Amount (USD)
            </label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
              <Input
                type="number"
                step="0.5"
                min={minAmount}
                placeholder={String(minAmount)}
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                className="pl-7 text-lg font-semibold"
                autoFocus
              />
            </div>
            <p className="text-[11px] text-muted-foreground mt-1">
              Minimum: ${minAmount}
            </p>
          </div>

          {/* Credit preview */}
          {numericAmount > 0 && (
            <div className="rounded-lg bg-accent/50 border border-border p-4 text-center">
              <div className="flex items-center justify-center gap-2">
                <Wallet className="h-5 w-5 text-primary" />
                <span className="text-sm text-muted-foreground">You'll get</span>
              </div>
              <div className="flex items-center justify-center gap-2 mt-1">
                <Badge className="gap-1 text-base px-3 py-1">
                  <Coins className="h-4 w-4" />
                  {calculatedCredits} credits
                </Badge>
              </div>
              <p className="text-[11px] text-muted-foreground mt-2">
                1 credit = 1 resume ranked • ${perResumeCost}/credit
              </p>
            </div>
          )}

          {/* Pay button */}
          <Button
            className="w-full"
            size="lg"
            onClick={handleBuy}
            disabled={buying || !isValid}
          >
            {buying ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : null}
            {numericAmount > 0 ? `Pay $${numericAmount.toFixed(2)}` : "Enter an amount"}
          </Button>
        </div>

        {/* Subscription upsell */}
        <div className="rounded-lg bg-primary/5 border border-primary/20 px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Crown className="h-4 w-4 text-primary" />
            <p className="text-xs font-medium text-foreground">Save more with a subscription plan</p>
          </div>
          <SubscriptionDialog
            trigger={
              <Button variant="ghost" size="sm" className="h-7 text-xs text-primary hover:text-primary gap-1">
                View Plans →
              </Button>
            }
          />
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default BuyCreditsDialog;

