import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import { Phone, Mail, FileText, Archive, MapPin, Download } from "lucide-react";
import { toast } from "sonner";
import type { Result } from "@/pages/Index";
import type { HiringStage } from "@/hooks/useStageTracker";

import CandidateSummary from "@/components/candidate/CandidateSummary";
import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
import ExperiencePanel from "@/components/candidate/ExperiencePanel";
import EducationPanel from "@/components/candidate/EducationPanel";
import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
import StageTracker from "@/components/candidate/StageTracker";
import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";

interface CandidateDetailSheetProps {
  result: Result | null;
  isOpen: boolean;
  onClose: () => void;
  jobId?: string | null;
  jobTitle?: string | null;
  formatCandidateName: (filename: string) => string;
  onDownload: (filePath: string, filename: string) => void;
  onDismiss: (resumeId: string) => void;
  currentStage?: HiringStage | null;
  stageUpdatedAt?: string | null;
  onStageChange?: (resumeId: string, stage: HiringStage) => void;
}

const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

const CandidateDetailSheet = ({
  result: r,
  isOpen,
  onClose,
  jobId,
  jobTitle,
  formatCandidateName,
  onDownload,
  onDismiss,
  currentStage,
  stageUpdatedAt,
  onStageChange,
}: CandidateDetailSheetProps) => {
  const [emailDialogOpen, setEmailDialogOpen] = useState(false);

  if (!r) return null;

  const strength = getStrengthLabel(r.overall_score);
  const candidateName = r.candidate_name || formatCandidateName(r.filename);

  return (
    <>
      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col gap-0">
          {/* Header */}
          <SheetHeader className="px-6 pt-6 pb-0 shrink-0 space-y-0">
            <div className="flex items-start justify-between gap-4 pr-6">
              <div className="min-w-0">
                <SheetTitle className="text-lg truncate">{candidateName}</SheetTitle>
                {(r.candidate_location || r.candidate_email) && (
                  <div className="flex items-center gap-2 mt-1 flex-wrap">
                    {r.candidate_location && (
                      <span className="flex items-center gap-1 text-xs text-muted-foreground">
                        <MapPin className="h-3 w-3" /> {r.candidate_location}
                      </span>
                    )}
                    {r.candidate_email && (
                      <span className="text-xs text-muted-foreground">{r.candidate_email}</span>
                    )}
                  </div>
                )}
              </div>
            </div>
          </SheetHeader>

          {/* Score bar + actions */}
          <div className="px-6 py-3 flex items-center gap-3 flex-wrap shrink-0">
            <div className="flex items-center gap-2.5">
              <span className="text-2xl font-semibold tabular-nums text-foreground">{r.overall_score?.toFixed(0)}%</span>
              <Badge variant={strength.variant}>{strength.label}</Badge>
              {r.scoring_version === "heuristic" && <Badge variant="secondary">Quick</Badge>}
            </div>

            <Separator orientation="vertical" className="h-5 hidden sm:block" />

            <TooltipProvider delayDuration={300}>
              <div className="flex items-center gap-0.5">
                {r.candidate_phone && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                        onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
                        <Phone className="h-3 w-3" /> Call
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>{r.candidate_phone}</TooltipContent>
                  </Tooltip>
                )}
                {r.candidate_email && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                        onClick={() => setEmailDialogOpen(true)}>
                        <Mail className="h-3 w-3" /> Email
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Send email</TooltipContent>
                  </Tooltip>
                )}
                {r.file_path && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                        onClick={() => onDownload(r.file_path!, r.filename)}>
                        <Download className="h-3 w-3" /> Resume
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Download resume</TooltipContent>
                  </Tooltip>
                )}
                <Tooltip>
