                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                        onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
                        <Phone className="h-3 w-3" /> Call
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>{r.candidate_phone}</TooltipContent>
                  </Tooltip>
                )}
                {r.candidate_email && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                        onClick={() => setEmailDialogOpen(true)}>
                        <Mail className="h-3 w-3" /> Email
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Send email</TooltipContent>
                  </Tooltip>
                )}
                {r.file_path && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                        onClick={() => onDownload(r.file_path!, r.filename)}>
                        <Download className="h-3 w-3" /> Resume
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Download resume</TooltipContent>
                  </Tooltip>
                )}
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-destructive"
                      onClick={() => { onDismiss(r.resume_id); onClose(); }}>
                      <Archive className="h-3.5 w-3.5" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Archive</TooltipContent>
                </Tooltip>
              </div>
            </TooltipProvider>
          </div>

          <Separator />

          {/* Scrollable panels */}
          <ScrollArea className="flex-1">
            <div className="px-6 py-5 space-y-5">
              <CandidateSummary result={r} />

              {onStageChange && (
                <StageTracker
                  currentStage={currentStage || "applied"}
                  updatedAt={stageUpdatedAt}
                  onStageChange={(stage) => onStageChange(r.resume_id, stage)}
                />
              )}

              <StrengthsGapsPanel result={r} />

              <div className="space-y-4">
                <SkillsDetailPanel result={r} />
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <ExperiencePanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves as string[]} />
                  <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
                </div>
              </div>

              <JDAlignedPanel result={r} />

              <InterviewQuestionsPanel result={r} />
            </div>
          </ScrollArea>
        </SheetContent>
      </Sheet>

      {r.candidate_email && (
        <EmailOutreachDialog
          open={emailDialogOpen}
          onOpenChange={setEmailDialogOpen}
          candidateName={candidateName}
          candidateEmail={r.candidate_email}
          jobTitle={jobTitle || "Open Position"}
          matchScore={Math.round(r.overall_score ?? 0)}
          resumeId={r.resume_id}
          jobId={jobId || ""}
        />
      )}
    </>
  );
};

