import { useState } from "react";
import { ChevronDown, ChevronUp } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { Result } from "@/pages/Index";

interface InterviewQuestionsPanelProps {
  result: Result;
}

const InterviewQuestionsPanel = ({ result: r }: InterviewQuestionsPanelProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const questions = r.interview_questions;

  if (!questions || !Array.isArray(questions) || questions.length === 0) return null;

  const remaining = questions.slice(1);
  if (remaining.length === 0) return null;

  return (
    <Card className="overflow-hidden">
      <button
        className="w-full px-4 py-3 flex items-center gap-2 hover:bg-muted/50 transition-colors"
        onClick={() => setIsOpen(!isOpen)}
      >
        <h4 className="text-sm font-medium text-foreground">Interview Questions</h4>
        <Badge variant="secondary" className="text-[11px] h-5">{remaining.length}</Badge>
        <div className="ml-auto">
          {isOpen ? <ChevronUp className="h-3.5 w-3.5 text-muted-foreground" /> : <ChevronDown className="h-3.5 w-3.5 text-muted-foreground" />}
        </div>
      </button>
      {isOpen && (
        <div className="border-t border-border px-4 py-3 space-y-3">
          {remaining.map((q: any, i: number) => (
            <div key={i} className="flex gap-3 text-sm leading-relaxed">
              <span className="text-muted-foreground/50 tabular-nums font-medium shrink-0 w-5 text-right">{i + 2}</span>
              <span className="text-foreground/85">{typeof q === "string" ? q : String(q)}</span>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
};

export default InterviewQuestionsPanel;

