import { Fragment } from "react";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import { XCircle } from "lucide-react";
import { STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
import { format } from "date-fns";

interface StageTrackerProps {
  currentStage: HiringStage;
  updatedAt?: string | null;
  onStageChange: (stage: HiringStage) => void;
  disabled?: boolean;
}

const STAGE_LABELS: Record<string, string> = {
  applied: "Applied",
  screened: "Screened",
  interview: "Interview",
  offer: "Offer",
  hired: "Hired",
};

const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled }: StageTrackerProps) => {
  const currentIndex = currentStage === "rejected" ? -1 : STAGE_ORDER.indexOf(currentStage);
  const isRejected = currentStage === "rejected";

  return (
    <div className="flex items-center gap-3 py-1">
      <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>

      {/* Dots + connectors + labels */}
      <div className="flex-1 min-w-0">
        {/* Top row: dots and connectors */}
        <div className="flex items-center">
          {STAGE_ORDER.map((stage, i) => {
            const isCompleted = !isRejected && i < currentIndex;
            const isCurrent = !isRejected && i === currentIndex;
            const isUpcoming = isRejected || i > currentIndex;

            return (
              <Fragment key={stage}>
                <TooltipProvider delayDuration={150}>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <button
                        disabled={disabled}
                        onClick={(e) => { e.stopPropagation(); onStageChange(stage); }}
                        className={cn(
                          "relative w-6 h-6 rounded-full flex items-center justify-center text-[11px] font-bold transition-all duration-150 shrink-0",
                          "focus:outline-none focus-visible:ring-2 focus-visible:ring-primary/40",
                          isCompleted && "bg-emerald-500 text-white dark:bg-emerald-600 shadow-sm",
                          isCurrent && "bg-primary text-primary-foreground ring-2 ring-primary/30 shadow-sm",
                          isUpcoming && "bg-muted border border-border text-muted-foreground",
                          !disabled && "cursor-pointer hover:scale-110 hover:shadow",
                          disabled && "cursor-default"
                        )}
                      >
                        {isCompleted ? "✓" : i + 1}
                      </button>
                    </TooltipTrigger>
                    <TooltipContent className="text-xs">
                      {isCompleted
                        ? `${STAGE_LABELS[stage]} — done`
                        : isCurrent
                        ? `${STAGE_LABELS[stage]} — current stage`
                        : `Move to ${STAGE_LABELS[stage]}`}
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>

                {i < STAGE_ORDER.length - 1 && (
                  <div className={cn(
                    "h-px flex-1 min-w-[16px] max-w-[48px] transition-colors duration-200 shrink-0",
                    i < currentIndex && !isRejected ? "bg-emerald-500" : "bg-border"
                  )} />
                )}
              </Fragment>
            );
          })}
        </div>

        {/* Bottom row: labels aligned under each dot */}
        <div className="flex items-start mt-1.5">
          {STAGE_ORDER.map((stage, i) => {
            const isCompleted = !isRejected && i < currentIndex;
            const isCurrent = !isRejected && i === currentIndex;

            return (
              <Fragment key={stage}>
                <span className={cn(
                  "w-6 text-center text-[11px] leading-none",
                  isCompleted && "text-emerald-600 dark:text-emerald-400",
                  isCurrent && "text-primary font-semibold",
                  !isCompleted && !isCurrent && "text-muted-foreground"
                )}>
                  {STAGE_LABELS[stage]}
                </span>
                {i < STAGE_ORDER.length - 1 && (
                  <div className="flex-1 min-w-[16px] max-w-[48px]" />
                )}
              </Fragment>
            );
          })}
        </div>
      </div>

      {/* Reject button — visible on all screen sizes */}
      <TooltipProvider delayDuration={150}>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              disabled={disabled}
              className={cn(
                "h-7 w-7 shrink-0",
                isRejected
                  ? "text-destructive bg-destructive/10 hover:bg-destructive/20"
                  : "text-muted-foreground/40 hover:text-destructive hover:bg-destructive/10"
              )}
              onClick={(e) => { e.stopPropagation(); onStageChange("rejected"); }}
            >
              <XCircle className="h-3.5 w-3.5" />
            </Button>
          </TooltipTrigger>
          <TooltipContent className="text-xs">
            {isRejected ? "Click any stage to restore" : "Reject candidate"}
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>

      {/* Rejected badge */}
      {isRejected && (
        <Badge variant="destructive" className="text-[11px] shrink-0">Rejected</Badge>
      )}

      {/* Updated timestamp */}
      {updatedAt && (() => {
        try {
          return (
            <span className="text-[11px] text-muted-foreground shrink-0">
              Updated {format(new Date(updatedAt), "MMM d")}
            </span>
          );
        } catch {
          return null;
        }
      })()}
    </div>
  );
};

export default StageTracker;

