import { CheckCircle2, XCircle } from "lucide-react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { Result } from "@/pages/Index";

interface JDAlignedPanelProps {
  result: Result;
}

type RecLevel = "success" | "secondary" | "warning" | "destructive";

const getRecommendation = (score: number, hardFit: boolean | undefined, isHeuristic: boolean): { text: string; label: string; variant: RecLevel } => {
  if (isHeuristic) return { text: "Needs full AI scoring for reliable recommendation", label: "Pending", variant: "warning" };
  if (score >= 70 && hardFit !== false) return { text: "Strong core fit, gaps are learnable", label: "Shortlist", variant: "success" };
  if (score >= 50 && hardFit !== false) return { text: "Decent match, review before interview", label: "Consider", variant: "secondary" };
  if (score >= 40) return { text: "Has strengths but missing critical items", label: "Review", variant: "warning" };
  return { text: "Significant gaps for this role", label: "Pass", variant: "destructive" };
};

const JDAlignedPanel = ({ result: r }: JDAlignedPanelProps) => {
  const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.map(String) : [];
  const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.map(String) : [];
  const strengths = Array.isArray(r.strengths_json) ? r.strengths_json.map(String) : [];
  const gaps = Array.isArray(r.gaps_json) ? r.gaps_json.map(String) : [];
  const confidence = r.confidence ?? 0;
  const interviewQs = Array.isArray(r.interview_questions) ? r.interview_questions.map(String) : [];
  const isHeuristic = r.scoring_version === "heuristic";
  const isInsufficient = r.scoring_version === "insufficient";

  if (isInsufficient) return null;

  const totalMustHave = matched.length + missing.length;
  const mustHavePercent = totalMustHave > 0 ? Math.round((matched.length / totalMustHave) * 100) : 0;

  const rawMatchedPref = r.explanation_json?.matched_preferred;
  const matchedPreferred: string[] = Array.isArray(rawMatchedPref) ? rawMatchedPref.map(String)
    : (isHeuristic ? [] : strengths.filter((s) => !matched.some((m) => s.toLowerCase().includes(m.toLowerCase()))));
  const rawMissingPref = r.explanation_json?.missing_preferred;
  const missingPreferred: string[] = Array.isArray(rawMissingPref) ? rawMissingPref.map(String)
    : (isHeuristic ? [] : gaps.filter((g) => !missing.some((m) => g.toLowerCase().includes(m.toLowerCase()))));
  const totalPreferred = matchedPreferred.length + missingPreferred.length;

  const rec = getRecommendation(r.overall_score, r.hard_fit, isHeuristic);

  if (totalMustHave === 0 && totalPreferred === 0 && !r.explanation_json?.why_ranked_here) return null;

  return (
    <Card>
      <CardHeader className="pb-3 px-5 pt-4 flex-row items-center justify-between gap-3 space-y-0 flex-wrap">
        <div className="flex items-center gap-3">
          <h4 className="text-sm font-medium text-foreground">JD Alignment</h4>
          {totalMustHave > 0 && (
            <span className="text-sm text-muted-foreground tabular-nums">{mustHavePercent}% match</span>
          )}
        </div>
        <div className="flex items-center gap-2">
          <Badge variant={rec.variant}>{rec.label}</Badge>
          {confidence > 0 && <Badge variant="outline" className="text-xs">{confidence}% confidence</Badge>}
        </div>
      </CardHeader>

      <CardContent className="px-5 pb-5 pt-0">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Must Have */}
          {totalMustHave > 0 && (
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <h5 className="text-xs font-medium text-muted-foreground">Must Have</h5>
                <span className="text-xs text-muted-foreground/60">{matched.length}/{totalMustHave}</span>
              </div>
              <div className="space-y-2">
                {matched.map((item, i) => (
                  <div key={`m-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                    <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                    <span className="text-foreground">{item}</span>
                  </div>
                ))}
                {missing.map((item, i) => (
                  <div key={`x-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                    <XCircle className="h-3.5 w-3.5 text-red-400 shrink-0 mt-0.5" />
                    <span className="text-muted-foreground/80">{item}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Preferred */}
          {totalPreferred > 0 && (
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <h5 className="text-xs font-medium text-muted-foreground">Preferred</h5>
                <span className="text-xs text-muted-foreground/60">{matchedPreferred.length}/{totalPreferred}</span>
              </div>
              <div className="space-y-2">
                {matchedPreferred.map((item, i) => (
                  <div key={`pm-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                    <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                    <span className="text-foreground">{item}</span>
                  </div>
                ))}
                {missingPreferred.map((item, i) => (
                  <div key={`px-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                    <XCircle className="h-3.5 w-3.5 text-red-400 shrink-0 mt-0.5" />
                    <span className="text-muted-foreground">{item}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* AI Insight */}
          <div className="space-y-3">
            <h5 className="text-xs font-medium text-muted-foreground">AI Insight</h5>

            {r.explanation_json?.why_ranked_here && (
              <p className="text-sm text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
            )}

            <p className="text-sm text-foreground leading-relaxed">{rec.text}</p>

            {interviewQs.length > 0 && (
              <div className="pt-2 border-t border-border space-y-1">
                <h6 className="text-xs text-muted-foreground font-medium">Interview focus</h6>
                <p className="text-sm text-muted-foreground leading-relaxed">{interviewQs[0]}</p>
              </div>
            )}

            {r.explanation_json?.key_tradeoffs && (
              <p className="text-sm text-muted-foreground/60 leading-relaxed">{r.explanation_json.key_tradeoffs}</p>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

export default JDAlignedPanel;

import { useState } from "react";
import { ChevronDown, ChevronUp } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { Result } from "@/pages/Index";

interface InterviewQuestionsPanelProps {
  result: Result;
}

const InterviewQuestionsPanel = ({ result: r }: InterviewQuestionsPanelProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const questions = r.interview_questions;

  if (!questions || !Array.isArray(questions) || questions.length === 0) return null;

  const remaining = questions.slice(1);
  if (remaining.length === 0) return null;

  return (
    <Card className="overflow-hidden">
