        </div>
      </button>
      {isOpen && (
        <div className="border-t border-border px-4 py-3 space-y-3">
          {remaining.map((q: any, i: number) => (
            <div key={i} className="flex gap-3 text-sm leading-relaxed">
              <span className="text-muted-foreground/50 tabular-nums font-medium shrink-0 w-5 text-right">{i + 2}</span>
              <span className="text-foreground/85">{typeof q === "string" ? q : String(q)}</span>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
};

export default InterviewQuestionsPanel;

import { useState } from "react";
import { ChevronDown, ChevronUp } from "lucide-react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import type { Result } from "@/pages/Index";

interface SkillsDetailPanelProps {
  result: Result;
}

type SkillLevel = "Expert" | "Adv" | "Good" | "Mid" | "Low" | "Gap";

const getSkillLevel = (score: number): SkillLevel => {
  if (score >= 90) return "Expert";
  if (score >= 70) return "Adv";
  if (score >= 55) return "Good";
  if (score >= 40) return "Mid";
  if (score >= 20) return "Low";
  return "Gap";
};

const SkillsDetailPanel = ({ result: r }: SkillsDetailPanelProps) => {
  const [showAll, setShowAll] = useState(false);
  const scores = r.category_scores_json;

  const entries = scores && typeof scores === "object" && !Array.isArray(scores)
    ? Object.entries(scores as Record<string, any>).map(([skill, data]) => {
        const score = data && typeof data === "object" ? (data.score ?? 0) : (typeof data === "number" ? data : 0);
        const clamped = Math.max(0, Math.min(score, 100));
        return { skill, score: clamped, level: getSkillLevel(clamped) };
      }).sort((a, b) => b.score - a.score)
    : [];

  const skillCount = entries.length;
  const overallScore = skillCount > 0
    ? Math.round(entries.reduce((sum, e) => sum + e.score, 0) / skillCount)
    : 0;

  const topSkills = entries.filter((e) => e.score >= 40).slice(0, 5);
  const gapSkills = entries.filter((e) => e.score < 40);

  return (
    <Card>
      <CardHeader className="pb-3 px-4 pt-4 flex-row items-center gap-2 space-y-0">
        <h4 className="text-sm font-medium text-foreground">Skills</h4>
        {skillCount > 0 && <Badge variant="secondary" className="text-[11px] h-5">{skillCount}</Badge>}
      </CardHeader>
      <CardContent className="px-4 pb-4 pt-0 space-y-4">
        {skillCount > 0 ? (
          <>
            {/* Score */}
            <div className="space-y-2">
              <div className="flex items-baseline gap-1">
                <span className="text-2xl font-semibold tabular-nums text-foreground">{overallScore}</span>
                <span className="text-xs text-muted-foreground">/100</span>
              </div>
              <Progress value={overallScore} className="h-1.5" />
            </div>

            {/* Top skills */}
            {topSkills.length > 0 && (
              <div className="flex flex-wrap gap-1.5">
                {topSkills.map((s) => (
                  <Badge key={s.skill} variant="secondary" className="text-xs font-normal">
                    {s.skill.replace(/_/g, " ")} · {s.level}
                  </Badge>
                ))}
              </div>
            )}

            {/* Gaps */}
            {gapSkills.length > 0 && (
              <div className="space-y-1.5 pt-3 border-t border-border">
                <h5 className="text-xs text-muted-foreground font-medium">Gaps</h5>
                {gapSkills.map((s) => (
                  <div key={s.skill} className="flex items-center justify-between text-sm py-0.5">
                    <span className="text-muted-foreground capitalize">{s.skill.replace(/_/g, " ")}</span>
                    <Badge variant="outline" className="text-[11px] h-5">{s.level}</Badge>
                  </div>
                ))}
              </div>
            )}

            {/* Expand */}
            {entries.length > 5 && (
              <button
                className="flex items-center justify-center gap-1 w-full text-xs text-muted-foreground hover:text-foreground transition-colors"
                onClick={() => setShowAll(!showAll)}
              >
                {showAll ? "Hide" : `View all ${skillCount}`}
                {showAll ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
              </button>
            )}

            {showAll && (
              <div className="space-y-1 pt-2 border-t border-border">
                {entries.map((e) => (
                  <div key={e.skill} className="flex items-center justify-between text-sm py-0.5">
                    <span className="text-muted-foreground capitalize truncate">{e.skill.replace(/_/g, " ")}</span>
                    <Badge variant="outline" className="text-[11px] h-5 shrink-0">{e.level}</Badge>
                  </div>
                ))}
              </div>
            )}
          </>
        ) : (
          <p className="text-sm text-muted-foreground">No skill data</p>
        )}
      </CardContent>
    </Card>
  );
};

export default SkillsDetailPanel;

