import { useCallback, useEffect, useState } from "react";
import SidebarLayout from "@/components/SidebarLayout";
import ChangePasswordCard from "@/components/settings/ChangePasswordCard";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { Mail, Calendar, Briefcase, FileText, Zap, Inbox, Crown } from "lucide-react";
import { FadeIn } from "@/components/ui/fade-in";
import { StaggerList } from "@/components/ui/stagger-list";

function getInitials(email?: string | null): string {
  if (!email) return "?";
  const name = email.split("@")[0];
  const parts = name.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name[0]?.toUpperCase() || "?";
}

function getUserName(email?: string | null): string {
  if (!email) return "User";
  return email.split("@")[0].replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

const Profile = () => {
  const { user, profile } = useAuth();
  const plan = profile?.plan ?? "free";
  const isPaid = plan !== "free";

  // Fetch usage stats
  const [stats, setStats] = useState<{ totalJobs: number; totalResumes: number; creditsUsed: number } | null>(null);
  const fetchStats = useCallback(async () => {
    if (!user) return;
    try {
      const [jobsRes, usageRes] = await Promise.all([
        supabase.from("jobs").select("id, resumes(count)").eq("user_id", user.id),
        supabase.from("usage_logs").select("credits_used").eq("user_id", user.id),
      ]);
      const jobs = jobsRes.data ?? [];
      const totalJobs = jobs.length;
      const totalResumes = jobs.reduce((sum: number, j: any) => sum + (j.resumes?.[0]?.count ?? 0), 0);
      const creditsUsed = (usageRes.data ?? []).reduce((sum: number, u: any) => sum + (u.credits_used ?? 0), 0);
      setStats({ totalJobs, totalResumes, creditsUsed });
    } catch { /* silent */ }
  }, [user]);
  useEffect(() => { fetchStats(); }, [fetchStats]);

  // Credits
  const sub = profile?.subscription_credits ?? 0;
  const top = profile?.topup_credits ?? 0;
  const bonus = profile?.bonus_credits ?? 0;
  const split = sub + top + bonus;
  const totalCredits = split > 0 ? split : (profile?.credits ?? 0);

  return (
    <SidebarLayout>
      <main className="mx-auto max-w-2xl px-4 sm:px-6 lg:px-8 py-8">
        <FadeIn>
          <h1 className="text-xl font-semibold text-foreground tracking-tight mb-6">Profile</h1>
        </FadeIn>
        <StaggerList className="space-y-6" stagger={0.08}>
          {/* Account card */}
          <Card>
            <CardContent className="p-6">
              <div className="flex items-center gap-4">
                <div className="h-14 w-14 rounded-full bg-primary text-primary-foreground text-lg font-bold flex items-center justify-center shrink-0">
                  {getInitials(user?.email)}
                </div>
                <div className="min-w-0 flex-1">
                  <h2 className="text-lg font-semibold text-foreground truncate">{getUserName(user?.email)}</h2>
                  <p className="text-sm text-muted-foreground truncate">{user?.email}</p>
                  <div className="flex items-center gap-2 mt-1.5">
                    <Badge variant={isPaid ? "default" : "secondary"} className="text-xs capitalize gap-1">
                      {isPaid && <Crown className="h-3 w-3" />}
                      {plan} plan
                    </Badge>
                    <Badge variant="outline" className="text-xs tabular-nums">{totalCredits} credits</Badge>
                  </div>
                </div>
              </div>

              <Separator className="my-5" />

              <div className="grid grid-cols-2 gap-4 text-sm">
                <div className="flex items-center gap-2.5">
                  <Mail className="h-4 w-4 text-muted-foreground" />
                  <div>
                    <p className="text-xs text-muted-foreground">Email</p>
                    <p className="text-foreground truncate">{user?.email}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2.5">
                  <Calendar className="h-4 w-4 text-muted-foreground" />
                  <div>
                    <p className="text-xs text-muted-foreground">Member since</p>
                    <p className="text-foreground">{user?.created_at ? new Date(user.created_at).toLocaleDateString("en-US", { month: "long", year: "numeric" }) : "—"}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2.5">
                  <Inbox className="h-4 w-4 text-muted-foreground" />
                  <div>
                    <p className="text-xs text-muted-foreground">Email inbox</p>
                    <p className="text-foreground">{profile?.email_enabled ? "Enabled" : "Disabled"}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2.5">
                  <Zap className="h-4 w-4 text-muted-foreground" />
                  <div>
                    <p className="text-xs text-muted-foreground">Subscription</p>
                    <p className="text-foreground">{profile?.subscription_ends_at ? `Until ${new Date(profile.subscription_ends_at).toLocaleDateString("en-US", { month: "short", year: "numeric" })}` : "None"}</p>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Usage stats */}
          <Card>
            <CardHeader className="pb-3 px-6 pt-5">
              <CardTitle className="text-sm font-medium">Activity</CardTitle>
            </CardHeader>
            <CardContent className="px-6 pb-5">
              {!stats ? (
                <div className="grid grid-cols-3 gap-4">
                  {[0, 1, 2].map((i) => (
                    <div key={i} className="space-y-1.5">
                      <Skeleton className="h-7 w-12" />
                      <Skeleton className="h-3 w-20" />
                    </div>
                  ))}
                </div>
              ) : (
                <div className="grid grid-cols-3 gap-4">
                  <div>
                    <div className="flex items-center gap-2">
                      <Briefcase className="h-4 w-4 text-muted-foreground" />
                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalJobs}</span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">Jobs created</p>
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <FileText className="h-4 w-4 text-muted-foreground" />
                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalResumes}</span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">Resumes ranked</p>
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <Zap className="h-4 w-4 text-muted-foreground" />
                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.creditsUsed}</span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">Credits used</p>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Change password */}
          <ChangePasswordCard />
        </StaggerList>
      </main>
    </SidebarLayout>
  );
};

export default Profile;

