import { useEffect, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

interface FeatureFlag {
  id: string;
  key: string;
  label: string;
  description: string;
  enabled: boolean;
  value_json: Record<string, any>;
  category: string;
}

/**
 * Hook to read all feature flags with real-time updates.
 * Returns a map of flag key → { enabled, value_json }.
 */
export function useFeatureFlags() {
  const qc = useQueryClient();

  const { data: flags, isLoading } = useQuery({
    queryKey: ["feature_flags"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("feature_flags")
        .select("*")
        .order("key");
      if (error) throw error;
      return data as FeatureFlag[];
    },
    staleTime: 60_000,
  });

  useEffect(() => {
    const channel = supabase
      .channel("feature_flags_realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "feature_flags" },
        () => {
          qc.invalidateQueries({ queryKey: ["feature_flags"] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [qc]);

  const flagMap = new Map<string, { enabled: boolean; value_json: Record<string, any> }>();
  flags?.forEach((f) => flagMap.set(f.key, { enabled: f.enabled, value_json: f.value_json }));

  return { flags: flagMap, isLoading };
}

/**
 * Hook to check a single feature flag by key.
 * Returns { enabled, value, isLoading }.
 */
export function useFeatureFlag(key: string) {
  const { flags, isLoading } = useFeatureFlags();
  const flag = flags.get(key);
  return {
    enabled: flag?.enabled ?? false,
    value: flag?.value_json ?? {},
    isLoading,
    ready: !isLoading,
  };
}

