          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 pt-2">
          {/* Quick amount buttons */}
          <div className="flex gap-2 flex-wrap">
            {QUICK_AMOUNTS.filter(a => a >= minAmount).map((a) => (
              <Button
                key={a}
                variant={numericAmount === a ? "default" : "outline"}
                size="sm"
                className="flex-1 min-w-[60px]"
                onClick={() => setAmount(String(a))}
              >
                ${a}
              </Button>
            ))}
          </div>

          {/* Amount input */}
          <div>
            <Label htmlFor="credit-amount" className="text-sm font-medium text-foreground mb-1.5 block">
              Custom Amount (USD) <span className="text-destructive">*</span>
            </Label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
              <Input
                id="credit-amount"
                type="number"
                step="0.5"
                min={minAmount}
                placeholder={String(minAmount)}
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                className="pl-7 text-lg font-semibold"
                autoFocus
              />
            </div>
            <p className="text-[11px] text-muted-foreground mt-1">
              Minimum: ${minAmount}
            </p>
          </div>

          {/* Credit preview */}
          {numericAmount > 0 && (
            <div className="rounded-lg bg-accent/50 border border-border p-4 text-center">
              <div className="flex items-center justify-center gap-2">
                <Wallet className="h-5 w-5 text-primary" />
                <span className="text-sm text-muted-foreground">You'll get</span>
              </div>
              <div className="flex items-center justify-center gap-2 mt-1">
                <Badge className="gap-1 text-base px-3 py-1">
                  <Coins className="h-4 w-4" />
                  {calculatedCredits} credits
                </Badge>
              </div>
              <p className="text-[11px] text-muted-foreground mt-2">
                1 credit = 1 resume ranked • ${perResumeCost}/credit
              </p>
            </div>
          )}

          {/* Pay button */}
          <Button
            className="w-full"
            size="lg"
            onClick={handleBuy}
            disabled={buying || !isValid}
          >
            {buying ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : null}
            {numericAmount > 0 ? `Pay $${numericAmount.toFixed(2)}` : "Enter an amount"}
          </Button>
        </div>

        {/* Subscription upsell */}
        <div className="rounded-lg bg-primary/5 border border-primary/20 px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Crown className="h-4 w-4 text-primary" />
            <p className="text-xs font-medium text-foreground">Save more with a subscription plan</p>
          </div>
          <SubscriptionDialog
            trigger={
              <Button variant="ghost" size="sm" className="h-7 text-xs text-primary hover:text-primary gap-1">
                View Plans →
              </Button>
            }
          />
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default BuyCreditsDialog;

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Crown, Loader2, Sparkles, Zap, Check, ArrowRight, ArrowDown, CalendarClock, XCircle } from "lucide-react";
import { format } from "date-fns";

interface SubscriptionDialogProps {
  trigger?: React.ReactNode;
}

const SubscriptionDialog = ({ trigger }: SubscriptionDialogProps) => {
  const { user, profile, refreshProfile } = useAuth();
  const [open, setOpen] = useState(false);
  const [buying, setBuying] = useState<string | null>(null);
  const [cancelling, setCancelling] = useState(false);
  const [confirmAction, setConfirmAction] = useState<{
    type: "upgrade" | "downgrade" | "cancel_subscription";
    planId?: string;
    planName?: string;
    price?: number;
  } | null>(null);
  const [downgrading, setDowngrading] = useState(false);

  const currentPlan = profile?.plan ?? "free";
  const isPaid = currentPlan !== "free";
  const subscriptionEndsAt = (profile as any)?.subscription_ends_at
    ? new Date((profile as any).subscription_ends_at)
    : null;
  const isExpired = subscriptionEndsAt ? subscriptionEndsAt < new Date() : false;
  const hasActiveSubscription = !!(profile as any)?.dodo_subscription_id;

  const { data: plans } = useQuery({
    queryKey: ["subscription_plans_active"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("plans")
        .select("*")
        .eq("active", true)
        .order("price");
      if (error) throw error;
      return data;
    },
  });

  const { data: config } = useQuery({
    queryKey: ["platform_config_payg"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("*")
        .limit(1)
        .single();
      if (error) return null;
      return data;
    },
  });

  const paygCost = (config as any)?.payg_per_resume_cost ?? 0.07;

  const handleSubscribe = async (planId: string) => {
    if (!user) return;
    setBuying(planId);

    try {
      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
        body: {
          plan_id: planId,
          return_url: `${window.location.origin}/payment/callback`,
        },
      });

      if (error) throw error;

      if (!data?.checkout_url) {
        toast.error(data?.error || "Failed to create checkout session");
        return;
      }

      // Redirect to Dodo hosted checkout
      window.location.href = data.checkout_url;
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setBuying(null);
    }
  };

  const handleCancelSubscription = async () => {
    setCancelling(true);
    try {
      const { error } = await supabase.functions.invoke("cancel-dodo-subscription", {});
      if (error) throw error;
      toast.success("Subscription will cancel at the end of your current billing period.");
      await refreshProfile();
      setConfirmAction(null);
    } catch (err: any) {
      toast.error("Failed to cancel: " + err.message);
    } finally {
      setCancelling(false);
    }
  };

  const handleDowngradeToPayg = async () => {
    setDowngrading(true);
    try {
      if (hasActiveSubscription) {
        const { data, error: cancelError } = await supabase.functions.invoke("cancel-dodo-subscription", {});
        if (cancelError || data?.error) {
          toast.error("Could not cancel subscription with payment provider. Please try again or contact support.");
          setDowngrading(false);
          return;
        }
      }
      const { error } = await supabase
        .from("profiles")
        .update({ plan: "free", subscription_ends_at: null, dodo_subscription_id: null } as any)
        .eq("user_id", user?.id);
