      toast.success("Switched to Pay As You Go. Your remaining credits are preserved.");
      await refreshProfile();
      setConfirmAction(null);
    } catch (err: any) {
      toast.error("Failed to downgrade: " + err.message);
    } finally {
      setDowngrading(false);
    }
  };

  const handleConfirmedAction = () => {
    if (!confirmAction) return;
    if (confirmAction.type === "upgrade" && confirmAction.planId) {
      handleSubscribe(confirmAction.planId);
      setConfirmAction(null);
    } else if (confirmAction.type === "downgrade") {
      handleDowngradeToPayg();
    } else if (confirmAction.type === "cancel_subscription") {
      handleCancelSubscription();
    }
  };

  return (
    <>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogTrigger asChild>
          {trigger || (
            <Button variant="outline" size="sm" className="gap-1.5">
              <Crown className="h-3.5 w-3.5" />
              Upgrade Plan
            </Button>
          )}
        </DialogTrigger>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-primary" />
              Choose Your Plan
            </DialogTitle>
            <DialogDescription>
              {isPaid
                ? "Manage your subscription or switch plans."
                : "Upgrade to save on every resume ranked. All plans auto-renew."}
            </DialogDescription>
          </DialogHeader>

          {/* Current Plan Banner */}
          <div className="rounded-lg border border-border bg-muted/50 px-4 py-3 flex items-center gap-3">
            <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/15">
              {isPaid ? <Crown className="h-4 w-4 text-primary" /> : <Zap className="h-4 w-4 text-primary" />}
            </div>
            <div className="flex-1">
              <p className="text-sm font-medium text-foreground">
                Current: {isPaid ? currentPlan : "Pay As You Go"}
              </p>
              <p className="text-xs text-muted-foreground">
                {isPaid
                  ? subscriptionEndsAt
                    ? isExpired
                      ? "Your subscription has expired"
                      : hasActiveSubscription
                        ? `Auto-renews ${format(subscriptionEndsAt, "MMM d, yyyy")}`
                        : `Expires ${format(subscriptionEndsAt, "MMM d, yyyy")}`
                    : "You're saving on every resume!"
                  : `$${paygCost}/resume • Upgrade to save more`}
              </p>
            </div>
            {isPaid && subscriptionEndsAt && !isExpired && (
              <Badge variant="secondary" className="text-xs gap-1">
                <CalendarClock className="h-3 w-3" />
                {format(subscriptionEndsAt, "MMM d")}
              </Badge>
            )}
            {isPaid && isExpired && (
              <Badge variant="destructive" className="text-xs">Expired</Badge>
            )}
            {!isPaid && (
              <Badge variant="secondary" className="text-xs">Active</Badge>
            )}
          </div>

          {/* Cancel Subscription Button */}
          {isPaid && hasActiveSubscription && !isExpired && (
            <Button
              variant="outline"
              size="sm"
              className="gap-1.5 text-xs border-destructive/30 text-destructive hover:bg-destructive/10"
              onClick={() => setConfirmAction({ type: "cancel_subscription" })}
              disabled={cancelling}
            >
              {cancelling ? <Loader2 className="h-3 w-3 animate-spin" /> : <XCircle className="h-3 w-3" />}
              Cancel Auto-Renewal
            </Button>
          )}

          {/* PAYG Card */}
          <div className={`rounded-lg border p-4 ${!isPaid ? "border-primary/50 bg-primary/5" : "border-border"}`}>
            <div className="flex items-center justify-between">
              <div>
                <div className="flex items-center gap-2">
                  <p className="font-semibold text-foreground">Pay As You Go</p>
                  {!isPaid && <Badge variant="default" className="text-[11px] px-1.5 py-0">Current</Badge>}
                </div>
                <p className="text-xs text-muted-foreground mt-1">No commitment • Buy credits anytime</p>
              </div>
              <div className="flex items-center gap-3">
                <div className="text-right">
                  <p className="text-lg font-bold text-foreground">$0</p>
                  <p className="text-xs text-muted-foreground">/month</p>
                </div>
                {isPaid && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="gap-1 h-8 text-xs border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
                    onClick={() => setConfirmAction({ type: "downgrade" })}
                  >
                    <ArrowDown className="h-3 w-3" />
                    Switch
                  </Button>
                )}
              </div>
            </div>
            <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
              <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> ${paygCost}/resume</span>
              <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> Credit top-ups</span>
            </div>
          </div>

          {/* Subscription Plans */}
          <div className="space-y-3">
            {plans?.map((plan: any, idx: number) => {
              const isCurrentPlan = currentPlan === plan.name;
              const savings = paygCost > 0 ? Math.round(((paygCost - (plan.per_resume_cost ?? 0.05)) / paygCost) * 100) : 0;
              const isPopular = idx === Math.floor((plans.length - 1) / 2);

              return (
                <div
                  key={plan.id}
                  className={`relative rounded-lg border p-4 transition-colors ${
                    isCurrentPlan
                      ? "border-primary/50 bg-primary/5"
                      : "border-border hover:border-primary/30 hover:bg-accent/30"
                  }`}
                >
                  {isPopular && !isCurrentPlan && (
                    <Badge className="absolute -top-2.5 right-3 bg-primary text-primary-foreground text-[11px] px-2 py-0.5">
                      Popular
                    </Badge>
                  )}
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="flex items-center gap-2">
                        <p className="font-semibold text-foreground">{plan.name}</p>
                        {isCurrentPlan && <Badge variant="default" className="text-[11px] px-1.5 py-0">Current</Badge>}
                        {savings > 0 && !isCurrentPlan && (
                          <Badge variant="secondary" className="text-[11px] px-1.5 py-0 text-primary">
                            Save {savings}%
                          </Badge>
                        )}
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">
                        {plan.billing_type} • {plan.credits} credits • Auto-renews
                      </p>
                    </div>
                    <div className="text-right">
                      <p className="text-lg font-bold text-foreground">${plan.price}</p>
                      <p className="text-xs text-muted-foreground">/{plan.billing_type === "yearly" ? "year" : "mo"}</p>
                    </div>
                  </div>
                  <div className="mt-3 flex items-center justify-between">
                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
                      <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> ${plan.per_resume_cost ?? 0.05}/resume</span>
                      <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> Credit top-ups</span>
                    </div>
                    {!isCurrentPlan && (
                      <Button
                        size="sm"
                        onClick={() =>
                          setConfirmAction({
                            type: "upgrade",
                            planId: plan.id,
                            planName: plan.name,
                            price: plan.price,
                          })
                        }
                        disabled={buying === plan.id}
                        className="gap-1 h-8"
                      >
                        {buying === plan.id ? (
                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <>
                            Subscribe <ArrowRight className="h-3 w-3" />
                          </>
                        )}
                      </Button>
                    )}
                  </div>
                </div>
              );
            })}
            {(!plans || plans.length === 0) && (
              <p className="text-sm text-muted-foreground text-center py-4">
                No subscription plans available right now. Please try again later or contact support.
              </p>
            )}
          </div>

          <p className="text-[11px] text-muted-foreground text-center pt-1">
            All plans auto-renew. Cancel anytime before your next billing date.
          </p>
        </DialogContent>
      </Dialog>

      {/* Confirmation AlertDialog */}
      <AlertDialog open={confirmAction !== null} onOpenChange={(o) => !o && setConfirmAction(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {confirmAction?.type === "upgrade"
                ? `Subscribe to ${confirmAction.planName}?`
                : confirmAction?.type === "cancel_subscription"
                  ? "Cancel Auto-Renewal?"
                  : "Switch to Pay As You Go?"}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {confirmAction?.type === "upgrade" ? (
                <>
                  You'll be redirected to our secure checkout page to complete payment of{" "}
                  <span className="font-semibold text-foreground">${confirmAction.price}</span>.
                  Your subscription will auto-renew each billing period.
                </>
              ) : confirmAction?.type === "cancel_subscription" ? (
                <>
                  Your subscription will remain active until the end of your current billing period.
                  After that, you'll be switched to Pay As You Go pricing. Your remaining credits will be preserved.
                </>
              ) : (
                <>
                  You'll switch back to Pay As You Go pricing at <span className="font-semibold text-foreground">${paygCost}/resume</span>.
                  Your remaining credits will be preserved and you can still purchase credit top-ups.
                  {hasActiveSubscription && " Your active subscription will also be cancelled."}
                </>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep Current Plan</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmedAction}
              disabled={downgrading || cancelling}
              className={confirmAction?.type !== "upgrade" ? "bg-destructive text-destructive-foreground hover:bg-destructive/90" : ""}
            >
              {(downgrading || cancelling) && <Loader2 className="h-4 w-4 animate-spin mr-1" />}
              {confirmAction?.type === "upgrade"
                ? "Proceed to Payment"
                : confirmAction?.type === "cancel_subscription"
                  ? "Cancel Auto-Renewal"
                  : "Confirm Downgrade"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

