                            {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
                          </p>
                        </div>
                        <Badge variant={job.status === "completed" ? "secondary" : "outline"} className="shrink-0 capitalize text-xs">
                          {job.status}
                        </Badge>
                      </CardContent>
                    </Card>
